__CR('t:stat',[{"t":"대푯값과 산포","l":[{"t":"평균·중앙값·최빈값","q":[{"t":"input","k":"평균 계산","q":"데이터 [2,4,4,4,5,5,7,9]의 평균은? (숫자만)","code":"[2,4,4,4,5,5,7,9]","a":["5"],"ex":"합 40을 개수 8로 나누면 40÷8=5 입니다."},{"t":"input","k":"중앙값","q":"정렬된 [2,4,4,4,5,5,7,9]의 중앙값은? (숫자만)","a":["4.5"],"ex":"값이 8개(짝수)이므로 4번째(4)와 5번째(5)의 평균, (4+5)÷2=4.5 입니다."},{"t":"choice","k":"이상치에 강함","q":"극단적인 이상치의 영향을 가장 적게 받는 대푯값은?","o":["평균","중앙값","합계","범위"],"a":1,"ex":"중앙값은 순서상 가운데 값이라 극단값에 흔들리지 않습니다."},{"t":"input","k":"이상치와 중앙값","q":"[1,2,3,4,100]의 중앙값은? (숫자만)","code":"[1,2,3,4,100]","a":["3"],"ex":"가운데(3번째) 값은 3입니다. 참고로 평균은 110÷5=22로 100의 영향을 크게 받습니다."},{"t":"choice","k":"최빈값","q":"[2,4,4,4,5,5,7,9]에서 가장 자주 나오는 값(최빈값)은?","o":["4","5","7","9"],"a":0,"ex":"4가 세 번 나와 가장 빈도가 높습니다."}],"th":{"sum":"**대푯값**(평균·중앙값·최빈값)은 데이터의 중심을, **산포**(분산·표준편차·IQR)는 흩어진 정도를 나타낸다. 이상치에는 중앙값이 가장 강건하다.","body":[{"h":"평균·중앙값·최빈값","t":"**평균**은 모든 값의 합을 개수로 나눈 값으로 이상치에 민감하다. **중앙값**은 정렬 후 가운데 값이라 이상치의 영향을 가장 적게 받는다. 예로 `[1,2,3,4,100]`의 평균은 22지만 중앙값은 3이다. **최빈값**은 가장 자주 나오는 값이다(`[2,4,4,4,5,5,7,9]`에서 4)."},{"h":"분산과 표준편차","t":"**분산**은 각 값이 평균에서 떨어진 거리의 제곱을 평균한 값, **표준편차**는 그 제곱근으로 데이터와 같은 단위를 갖는다. 표준편차가 크다는 것은 값들이 평균에서 멀리 퍼져 있음을 뜻한다. **IQR**(Q3−Q1)은 가운데 50% 범위로 이상치 탐지에 쓰인다."}],"code":{"c":"data = [2,4,4,4,5,5,7,9]\n# 평균 = 40/8 = 5\n# 중앙값 = (4+5)/2 = 4.5\n# 최빈값 = 4 (3번 등장)\n# 표준편차 클수록 평균에서 넓게 퍼짐","cap":"평균은 이상치에 민감, 중앙값은 강건"},"key":["평균=합/개수(이상치 민감), 중앙값=정렬 후 가운데(강건)","이상치가 있으면 중앙값이 대표값으로 적절","표준편차 = 분산의 제곱근, 클수록 넓게 퍼짐","IQR=Q3−Q1, 가운데 50% 범위"]}},{"t":"분산과 표준편차","q":[{"t":"input","k":"평균","q":"[1,2,3,4,5]의 평균은? (숫자만)","a":["3"],"ex":"합 15을 5로 나누면 3입니다."},{"t":"choice","k":"모분산","q":"편차제곱합이 10일 때 모분산(population, n으로 나눔)은?","o":["2","2.5","5","10"],"a":0,"ex":"모분산은 10÷5=2 입니다. 표본분산(2.5)과 나누는 수가 다릅니다."},{"t":"choice","k":"표준편차 의미","q":"표준편차가 크다는 것은 무엇을 뜻하나요?","o":["데이터가 평균 주변에 몰려 있다","데이터가 평균에서 넓게 퍼져 있다","평균이 크다","데이터 개수가 많다"],"a":1,"ex":"표준편차는 값들이 평균에서 흩어진 정도를 나타냅니다."},{"t":"choice","k":"편차제곱합","q":"[1,2,3,4,5]에서 (각 값 − 평균)²의 합은?","o":["5","10","15","2"],"a":1,"ex":"편차 −2,−1,0,1,2의 제곱은 4,1,0,1,4이고 합은 10입니다."},{"t":"choice","k":"표본분산","q":"편차제곱합이 10일 때 표본분산(sample, n−1로 나눔)은?","o":["2","2.5","5","10"],"a":1,"ex":"표본분산은 10÷(5−1)=10÷4=2.5 입니다."}],"th":{"sum":"**대푯값**(평균·중앙값·최빈값)은 데이터의 중심을, **산포**(분산·표준편차·IQR)는 흩어진 정도를 나타낸다. 이상치에는 중앙값이 가장 강건하다.","body":[{"h":"분산과 표준편차","t":"**분산**은 각 값이 평균에서 떨어진 거리의 제곱을 평균한 값, **표준편차**는 그 제곱근으로 데이터와 같은 단위를 갖는다. 표준편차가 크다는 것은 값들이 평균에서 멀리 퍼져 있음을 뜻한다. **IQR**(Q3−Q1)은 가운데 50% 범위로 이상치 탐지에 쓰인다."},{"h":"평균·중앙값·최빈값","t":"**평균**은 모든 값의 합을 개수로 나눈 값으로 이상치에 민감하다. **중앙값**은 정렬 후 가운데 값이라 이상치의 영향을 가장 적게 받는다. 예로 `[1,2,3,4,100]`의 평균은 22지만 중앙값은 3이다. **최빈값**은 가장 자주 나오는 값이다(`[2,4,4,4,5,5,7,9]`에서 4)."}],"code":{"c":"data = [2,4,4,4,5,5,7,9]\n# 평균 = 40/8 = 5\n# 중앙값 = (4+5)/2 = 4.5\n# 최빈값 = 4 (3번 등장)\n# 표준편차 클수록 평균에서 넓게 퍼짐","cap":"평균은 이상치에 민감, 중앙값은 강건"},"key":["평균=합/개수(이상치 민감), 중앙값=정렬 후 가운데(강건)","이상치가 있으면 중앙값이 대표값으로 적절","표준편차 = 분산의 제곱근, 클수록 넓게 퍼짐","IQR=Q3−Q1, 가운데 50% 범위"]}},{"t":"범위·IQR·정규분포","q":[{"t":"input","k":"범위","q":"[4,8,15,16,23,42]의 범위(range)는? (숫자만)","code":"[4,8,15,16,23,42]","a":["38"],"ex":"최댓값 42 − 최솟값 4 = 38 입니다."},{"t":"input","k":"IQR","q":"[1,2,3,4,5,6,7,8]에서 Q1=2.5, Q3=6.5 일 때 IQR은? (숫자만)","a":["4"],"ex":"IQR = Q3 − Q1 = 6.5 − 2.5 = 4 입니다."},{"t":"choice","k":"95·99.7 규칙","q":"68-95-99.7 규칙으로 옳은 설명은?","o":["±2σ≈95%, ±3σ≈99.7%","±2σ≈68%, ±3σ≈95%","±2σ≈50%, ±3σ≈68%","±2σ≈99.7%, ±3σ≈100%"],"a":0,"ex":"±2σ 안에 약 95%, ±3σ 안에 약 99.7%가 들어갑니다."},{"t":"choice","k":"68 규칙","q":"정규분포에서 평균 ±1 표준편차 구간에는 약 몇 %의 데이터가 들어가나요?","o":["68%","95%","99.7%","50%"],"a":0,"ex":"68-95-99.7 규칙에 따라 ±1σ 안에는 약 68%가 들어갑니다."},{"t":"choice","k":"양의 왜도","q":"오른쪽으로 긴 꼬리를 가진(양의 왜도) 분포에서 일반적으로 성립하는 관계는?","o":["평균 &gt; 중앙값","평균 &lt; 중앙값","평균 = 중앙값","최빈값이 존재하지 않음"],"a":0,"ex":"오른쪽 꼬리의 큰 값들이 평균을 끌어올려 평균이 중앙값보다 커집니다."}],"th":{"sum":"**대푯값**(평균·중앙값·최빈값)은 데이터의 중심을, **산포**(분산·표준편차·IQR)는 흩어진 정도를 나타낸다. 이상치에는 중앙값이 가장 강건하다.","body":[{"h":"평균·중앙값·최빈값","t":"**평균**은 모든 값의 합을 개수로 나눈 값으로 이상치에 민감하다. **중앙값**은 정렬 후 가운데 값이라 이상치의 영향을 가장 적게 받는다. 예로 `[1,2,3,4,100]`의 평균은 22지만 중앙값은 3이다. **최빈값**은 가장 자주 나오는 값이다(`[2,4,4,4,5,5,7,9]`에서 4)."},{"h":"분산과 표준편차","t":"**분산**은 각 값이 평균에서 떨어진 거리의 제곱을 평균한 값, **표준편차**는 그 제곱근으로 데이터와 같은 단위를 갖는다. 표준편차가 크다는 것은 값들이 평균에서 멀리 퍼져 있음을 뜻한다. **IQR**(Q3−Q1)은 가운데 50% 범위로 이상치 탐지에 쓰인다."}],"code":{"c":"data = [2,4,4,4,5,5,7,9]\n# 평균 = 40/8 = 5\n# 중앙값 = (4+5)/2 = 4.5\n# 최빈값 = 4 (3번 등장)\n# 표준편차 클수록 평균에서 넓게 퍼짐","cap":"평균은 이상치에 민감, 중앙값은 강건"},"key":["평균=합/개수(이상치 민감), 중앙값=정렬 후 가운데(강건)","이상치가 있으면 중앙값이 대표값으로 적절","표준편차 = 분산의 제곱근, 클수록 넓게 퍼짐","IQR=Q3−Q1, 가운데 50% 범위"]}}]},{"t":"확률과 분포","l":[{"t":"확률 기초","q":[{"t":"input","k":"동전 둘 다 앞","q":"공정한 동전 2개를 던져 둘 다 앞면일 확률은? (예: 1/4)","a":["1/4","0.25"],"ex":"1/2 × 1/2 = 1/4 입니다."},{"t":"choice","k":"주사위 짝수","q":"공정한 주사위 한 개를 던져 짝수가 나올 확률은?","o":["1/6","1/3","1/2","2/3"],"a":2,"ex":"짝수는 2,4,6 세 가지이므로 3/6=1/2 입니다."},{"t":"choice","k":"독립사건 곱","q":"두 사건 A, B가 독립일 때 P(A와 B가 모두 일어남)은?","o":["P(A)+P(B)","P(A)×P(B)","P(A)−P(B)","P(A)/P(B)"],"a":1,"ex":"독립사건은 확률을 곱합니다: P(A∩B)=P(A)×P(B)."},{"t":"choice","k":"주사위 둘 다 6","q":"공정한 주사위 2개를 던져 둘 다 6이 나올 확률은?","o":["1/12","1/36","1/6","1/18"],"a":1,"ex":"독립이므로 1/6 × 1/6 = 1/36 입니다."},{"t":"choice","k":"조건부확률","q":"조건부확률 P(A|B)의 의미로 옳은 것은?","o":["A가 일어난 조건에서 B가 일어날 확률","B가 일어났다는 조건에서 A가 일어날 확률","A와 B가 동시에 일어날 확률","A 또는 B가 일어날 확률"],"a":1,"ex":"P(A|B)는 B라는 조건이 주어졌을 때 A의 확률입니다."}],"th":{"sum":"확률은 사건 발생 가능성(0~1)이다. **독립**이면 곱셈으로, **이항분포**는 성공/실패 반복을, **중심극한정리(CLT)**는 표본평균이 정규분포에 가까워짐을 말한다.","body":[{"h":"확률과 독립","t":"공정한 주사위에서 짝수 확률은 3/6=1/2다. 두 사건이 **독립**이면 `P(A와 B)=P(A)×P(B)` — 동전 2개 모두 앞면은 1/2×1/2=1/4, 주사위 둘 다 6은 1/6×1/6=1/36이다. **조건부확률** `P(A|B)`는 B가 일어났다는 조건에서 A가 일어날 확률이다."},{"h":"이항분포와 CLT","t":"**이항분포**는 성공 확률 p인 시행을 n번 반복할 때 성공 횟수의 분포다. 동전 3번에 앞면 2번 확률은 `C(3,2)×0.5³=3/8`. **중심극한정리**에 따라 표본 크기가 커지면 모집단 분포와 무관하게 표본평균의 분포가 정규분포에 근사한다. **표준화**(z=(x−μ)/σ)로 서로 다른 분포를 비교한다."}],"code":{"c":"# 독립 사건: P(A∩B) = P(A)·P(B)\n# 동전 3번 중 앞면 정확히 2번\n# C(3,2) × 0.5^2 × 0.5^1 = 3 × 0.125 = 0.375 (3/8)","cap":"이항분포 P(X=k)=C(n,k)·p^k·(1-p)^(n-k)"},"key":["독립 사건: P(A∩B)=P(A)×P(B)","이항분포=성공/실패 n번 반복의 성공 횟수 분포","CLT: 표본이 커지면 표본평균이 정규분포에 근사","표준화 z=(x−μ)/σ로 분포 비교"]}},{"t":"분포와 표본","q":[{"t":"choice","k":"앞면 2번","q":"공정한 동전을 3번 던져 앞면이 정확히 2번 나올 확률은?","o":["1/8","2/8","3/8","4/8"],"a":2,"ex":"경우의 수 C(3,2)=3, 각 확률 (1/2)³=1/8, 따라서 3×1/8=3/8 입니다."},{"t":"input","k":"모두 앞면","q":"공정한 동전을 3번 던져 모두 앞면일 확률은? (예: 1/8)","a":["1/8","0.125"],"ex":"(1/2)³ = 1/8 입니다."},{"t":"choice","k":"정규분포 모양","q":"정규분포의 모양으로 옳은 것은?","o":["좌우 대칭인 종 모양","오른쪽으로만 치우친 모양","평평한 직선","계단 모양"],"a":0,"ex":"정규분포는 평균을 중심으로 좌우 대칭인 종 모양입니다."},{"t":"choice","k":"이항분포 상황","q":"이항분포로 모형화하기 적절한 상황은?","o":["성공/실패 두 결과를 가진 시행을 n번 반복","연속적인 키를 측정","순서 없는 이름 목록","시간에 따른 온도 변화"],"a":0,"ex":"이항분포는 성공/실패 두 결과의 독립 시행을 n번 반복할 때의 성공 횟수 분포입니다."},{"t":"choice","k":"표본 vs 모집단","q":"표본(sample)과 모집단(population)의 관계로 옳은 것은?","o":["모집단은 전체, 표본은 그 일부","표본이 모집단보다 항상 크다","둘은 같은 말이다","모집단은 표본의 일부다"],"a":0,"ex":"모집단은 관심 대상 전체, 표본은 거기서 뽑은 일부입니다."}],"th":{"sum":"확률은 사건 발생 가능성(0~1)이다. **독립**이면 곱셈으로, **이항분포**는 성공/실패 반복을, **중심극한정리(CLT)**는 표본평균이 정규분포에 가까워짐을 말한다.","body":[{"h":"확률과 독립","t":"공정한 주사위에서 짝수 확률은 3/6=1/2다. 두 사건이 **독립**이면 `P(A와 B)=P(A)×P(B)` — 동전 2개 모두 앞면은 1/2×1/2=1/4, 주사위 둘 다 6은 1/6×1/6=1/36이다. **조건부확률** `P(A|B)`는 B가 일어났다는 조건에서 A가 일어날 확률이다."},{"h":"이항분포와 CLT","t":"**이항분포**는 성공 확률 p인 시행을 n번 반복할 때 성공 횟수의 분포다. 동전 3번에 앞면 2번 확률은 `C(3,2)×0.5³=3/8`. **중심극한정리**에 따라 표본 크기가 커지면 모집단 분포와 무관하게 표본평균의 분포가 정규분포에 근사한다. **표준화**(z=(x−μ)/σ)로 서로 다른 분포를 비교한다."}],"code":{"c":"# 독립 사건: P(A∩B) = P(A)·P(B)\n# 동전 3번 중 앞면 정확히 2번\n# C(3,2) × 0.5^2 × 0.5^1 = 3 × 0.125 = 0.375 (3/8)","cap":"이항분포 P(X=k)=C(n,k)·p^k·(1-p)^(n-k)"},"key":["독립 사건: P(A∩B)=P(A)×P(B)","이항분포=성공/실패 n번 반복의 성공 횟수 분포","CLT: 표본이 커지면 표본평균이 정규분포에 근사","표준화 z=(x−μ)/σ로 분포 비교"]}},{"t":"중심극한정리와 표준화","q":[{"t":"choice","k":"z-score 공식","q":"표준화(z-score) 공식으로 옳은 것은?","o":["(x − μ) / σ","(x + μ) / σ","x × σ + μ","(μ − σ) / x"],"a":0,"ex":"z = (값 − 평균) ÷ 표준편차 로 평균 0, 표준편차 1 척도로 바꿉니다."},{"t":"input","k":"z 계산1","q":"평균 70, 표준편차 5인 분포에서 값 80의 z-score는? (숫자만)","a":["2"],"ex":"(80 − 70) ÷ 5 = 10 ÷ 5 = 2 입니다."},{"t":"input","k":"z 계산2","q":"평균 75, 표준편차 10인 분포에서 값 85의 z-score는? (숫자만)","a":["1"],"ex":"(85 − 75) ÷ 10 = 1 입니다."},{"t":"choice","k":"z=0 의미","q":"어떤 값의 z-score가 0이라면 그 값은?","o":["평균과 같다","최댓값이다","최솟값이다","이상치다"],"a":0,"ex":"z=0은 (값 − 평균)=0, 즉 값이 평균과 같다는 뜻입니다."},{"t":"choice","k":"중심극한정리","q":"중심극한정리(CLT)가 말하는 내용은?","o":["표본 크기가 커지면 표본평균의 분포가 정규분포에 가까워진다","모든 데이터는 정규분포를 따른다","표본이 크면 평균이 0이 된다","표준편차는 항상 1이다"],"a":0,"ex":"모집단 분포와 무관하게 표본 크기가 커질수록 표본평균의 분포는 정규분포에 근접합니다."}],"th":{"sum":"확률은 사건 발생 가능성(0~1)이다. **독립**이면 곱셈으로, **이항분포**는 성공/실패 반복을, **중심극한정리(CLT)**는 표본평균이 정규분포에 가까워짐을 말한다.","body":[{"h":"확률과 독립","t":"공정한 주사위에서 짝수 확률은 3/6=1/2다. 두 사건이 **독립**이면 `P(A와 B)=P(A)×P(B)` — 동전 2개 모두 앞면은 1/2×1/2=1/4, 주사위 둘 다 6은 1/6×1/6=1/36이다. **조건부확률** `P(A|B)`는 B가 일어났다는 조건에서 A가 일어날 확률이다."},{"h":"이항분포와 CLT","t":"**이항분포**는 성공 확률 p인 시행을 n번 반복할 때 성공 횟수의 분포다. 동전 3번에 앞면 2번 확률은 `C(3,2)×0.5³=3/8`. **중심극한정리**에 따라 표본 크기가 커지면 모집단 분포와 무관하게 표본평균의 분포가 정규분포에 근사한다. **표준화**(z=(x−μ)/σ)로 서로 다른 분포를 비교한다."}],"code":{"c":"# 독립 사건: P(A∩B) = P(A)·P(B)\n# 동전 3번 중 앞면 정확히 2번\n# C(3,2) × 0.5^2 × 0.5^1 = 3 × 0.125 = 0.375 (3/8)","cap":"이항분포 P(X=k)=C(n,k)·p^k·(1-p)^(n-k)"},"key":["독립 사건: P(A∩B)=P(A)×P(B)","이항분포=성공/실패 n번 반복의 성공 횟수 분포","CLT: 표본이 커지면 표본평균이 정규분포에 근사","표준화 z=(x−μ)/σ로 분포 비교"]}}]},{"t":"추론과 검정","l":[{"t":"가설검정 기초","q":[{"t":"choice","k":"p-value 작음","q":"p-value가 매우 작을 때(예: 0.01 &lt; α=0.05) 올바른 결정은?","o":["귀무가설을 기각한다","귀무가설을 채택한다","검정을 중단한다","표본을 버린다"],"a":0,"ex":"p-value가 유의수준보다 작으면 귀무가설을 기각합니다."},{"t":"choice","k":"대립가설","q":"대립가설(H1)에 대한 설명으로 옳은 것은?","o":["효과나 차이가 있다는 가설","효과가 없다는 가설","표본 크기를 뜻함","항상 기각되는 가설"],"a":0,"ex":"대립가설은 귀무가설과 반대로 효과/차이가 존재한다는 주장입니다."},{"t":"choice","k":"유의수준 값","q":"유의수준 α로 가장 흔히 쓰이는 값은?","o":["0.5","0.05","5","0.95"],"a":1,"ex":"관례적으로 α=0.05(5%)를 많이 사용합니다."},{"t":"choice","k":"p-value 의미","q":"p-value의 의미로 옳은 것은?","o":["귀무가설이 참이라 가정할 때 관측된 결과(또는 더 극단적인 결과)가 나올 확률","귀무가설이 참일 확률","대립가설이 참일 확률","표본의 평균값"],"a":0,"ex":"p-value는 H0가 참일 때 이 정도 이상 극단적인 결과가 관측될 확률입니다."},{"t":"choice","k":"귀무가설","q":"귀무가설(H0)에 대한 설명으로 가장 적절한 것은?","o":["효과나 차이가 없다는 기본 가설","연구자가 증명하고 싶은 가설","항상 참인 가설","표본 크기를 정하는 규칙"],"a":0,"ex":"귀무가설은 보통 '차이/효과가 없다'는 기준 가설입니다."}],"th":{"sum":"**가설검정**은 귀무가설(H0)을 기준으로 데이터가 얼마나 이례적인지 **p-value**로 판단한다. p-value가 유의수준 α보다 작으면 H0을 기각한다.","body":[{"h":"귀무가설과 p-value","t":"**귀무가설 H0**은 '차이·효과가 없다'는 기본 주장, **대립가설 H1**은 그 반대(효과가 있다)다. **p-value**는 H0이 참이라고 가정할 때 관측된 값 이상으로 극단적인 결과가 나올 확률이다. p-value가 α(흔히 0.05)보다 작으면 H0을 **기각**한다 — 예로 p=0.01<0.05면 H0 기각. p-value는 'H0이 참일 확률'이 아님에 주의한다."},{"h":"두 종류 오류·상관과 인과","t":"**1종 오류(Type I)**는 참인 H0을 잘못 기각(거짓 양성), **2종 오류(Type II)**는 거짓인 H0을 기각하지 못함(거짓 음성)이다. α는 1종 오류 허용 확률이다. **상관관계는 인과관계가 아니다** — 두 변수가 함께 움직여도 한쪽이 다른 쪽의 원인이라 단정할 수 없다(교란변수 가능성)."}],"code":{"c":"# p-value < α  → H0 기각\n# 예: p = 0.01, α = 0.05 → 기각\n# 1종 오류: 참인 H0을 기각 (거짓 양성)\n# 2종 오류: 거짓인 H0을 채택 (거짓 음성)","cap":"p<α면 H0 기각, α는 1종 오류 허용 수준"},"key":["H0=효과 없음, H1=효과 있음","p-value<α면 H0 기각 (α는 흔히 0.05)","p-value는 'H0이 참일 확률'이 아니다","1종 오류=참 H0 기각, 2종 오류=거짓 H0 못 기각; 상관≠인과"]}},{"t":"오류와 신뢰구간","q":[{"t":"choice","k":"α의 확률","q":"유의수준 α=0.05는 무엇을 범할 확률인가요?","o":["1종 오류","2종 오류","측정 오차","표본 오차"],"a":0,"ex":"α는 참인 귀무가설을 기각할 확률, 즉 1종 오류의 확률입니다."},{"t":"choice","k":"신뢰수준↑","q":"신뢰수준을 95%에서 99%로 높이면 신뢰구간의 폭은?","o":["넓어진다","좁아진다","변하지 않는다","0이 된다"],"a":0,"ex":"더 확신하려면 더 넓은 구간이 필요하므로 폭이 넓어집니다."},{"t":"choice","k":"1종 오류","q":"1종 오류(Type I error)에 해당하는 것은?","o":["참인 귀무가설을 기각함(거짓 양성)","거짓인 귀무가설을 기각함","참인 귀무가설을 채택함","표본을 잘못 뽑음"],"a":0,"ex":"1종 오류는 실제로 참인 H0를 잘못 기각하는 거짓 양성입니다."},{"t":"choice","k":"2종 오류","q":"2종 오류(Type II error)에 해당하는 것은?","o":["거짓인 귀무가설을 기각하지 못함(거짓 음성)","참인 귀무가설을 기각함","p-value를 잘못 계산함","표준편차를 잘못 씀"],"a":0,"ex":"2종 오류는 실제로 거짓인 H0를 기각하지 못하는 거짓 음성입니다."},{"t":"choice","k":"신뢰구간 해석","q":"95% 신뢰구간의 해석으로 가장 적절한 것은?","o":["같은 방법으로 반복 추정하면 약 95%의 구간이 참값을 포함한다","참값이 이 구간에 있을 확률이 정확히 95%다","표본의 95%가 이 구간에 있다","항상 참값을 포함한다"],"a":0,"ex":"신뢰수준은 반복 시행 시 구간이 모수를 포함하는 비율로 해석합니다."}],"th":{"sum":"**가설검정**은 귀무가설(H0)을 기준으로 데이터가 얼마나 이례적인지 **p-value**로 판단한다. p-value가 유의수준 α보다 작으면 H0을 기각한다.","body":[{"h":"귀무가설과 p-value","t":"**귀무가설 H0**은 '차이·효과가 없다'는 기본 주장, **대립가설 H1**은 그 반대(효과가 있다)다. **p-value**는 H0이 참이라고 가정할 때 관측된 값 이상으로 극단적인 결과가 나올 확률이다. p-value가 α(흔히 0.05)보다 작으면 H0을 **기각**한다 — 예로 p=0.01<0.05면 H0 기각. p-value는 'H0이 참일 확률'이 아님에 주의한다."},{"h":"두 종류 오류·상관과 인과","t":"**1종 오류(Type I)**는 참인 H0을 잘못 기각(거짓 양성), **2종 오류(Type II)**는 거짓인 H0을 기각하지 못함(거짓 음성)이다. α는 1종 오류 허용 확률이다. **상관관계는 인과관계가 아니다** — 두 변수가 함께 움직여도 한쪽이 다른 쪽의 원인이라 단정할 수 없다(교란변수 가능성)."}],"code":{"c":"# p-value < α  → H0 기각\n# 예: p = 0.01, α = 0.05 → 기각\n# 1종 오류: 참인 H0을 기각 (거짓 양성)\n# 2종 오류: 거짓인 H0을 채택 (거짓 음성)","cap":"p<α면 H0 기각, α는 1종 오류 허용 수준"},"key":["H0=효과 없음, H1=효과 있음","p-value<α면 H0 기각 (α는 흔히 0.05)","p-value는 'H0이 참일 확률'이 아니다","1종 오류=참 H0 기각, 2종 오류=거짓 H0 못 기각; 상관≠인과"]}},{"t":"상관과 인과","q":[{"t":"input","k":"r 최댓값","q":"상관계수 r가 가질 수 있는 최댓값은? (숫자만)","a":["1"],"ex":"완전한 양의 선형관계일 때 r=1 입니다."},{"t":"choice","k":"r≈0 의미","q":"상관계수 r가 0에 가까우면 두 변수는?","o":["선형관계가 약하다","완전한 양의 관계다","완전한 음의 관계다","항상 인과관계다"],"a":0,"ex":"r가 0 근처면 선형적 연관성이 거의 없음을 뜻합니다(비선형 관계는 별개)."},{"t":"choice","k":"상관계수 범위","q":"상관계수 r가 가질 수 있는 값의 범위는?","o":["−1 ~ 1","0 ~ 1","−100 ~ 100","0 ~ 100"],"a":0,"ex":"상관계수는 항상 −1 이상 1 이하입니다."},{"t":"choice","k":"r=-1 의미","q":"상관계수 r = −1이 의미하는 것은?","o":["완전한 음의 선형관계","관계가 전혀 없음","완전한 양의 선형관계","비선형 관계"],"a":0,"ex":"r=−1은 한 변수가 커질 때 다른 변수가 정확히 직선으로 감소하는 완전한 음의 선형관계입니다."},{"t":"choice","k":"상관≠인과","q":"'아이스크림 판매량과 익사 사고가 함께 늘어난다'가 보여주는 교훈은?","o":["상관관계가 곧 인과관계를 뜻하지는 않는다(더운 날씨라는 제3의 변수)","아이스크림이 익사를 유발한다","익사가 아이스크림 판매를 늘린다","둘은 아무 관계가 없다"],"a":0,"ex":"둘 다 '더운 날씨'라는 공통 요인의 영향을 받는 것으로, 상관이 인과를 의미하진 않습니다."}],"th":{"sum":"**가설검정**은 귀무가설(H0)을 기준으로 데이터가 얼마나 이례적인지 **p-value**로 판단한다. p-value가 유의수준 α보다 작으면 H0을 기각한다.","body":[{"h":"두 종류 오류·상관과 인과","t":"**1종 오류(Type I)**는 참인 H0을 잘못 기각(거짓 양성), **2종 오류(Type II)**는 거짓인 H0을 기각하지 못함(거짓 음성)이다. α는 1종 오류 허용 확률이다. **상관관계는 인과관계가 아니다** — 두 변수가 함께 움직여도 한쪽이 다른 쪽의 원인이라 단정할 수 없다(교란변수 가능성)."},{"h":"귀무가설과 p-value","t":"**귀무가설 H0**은 '차이·효과가 없다'는 기본 주장, **대립가설 H1**은 그 반대(효과가 있다)다. **p-value**는 H0이 참이라고 가정할 때 관측된 값 이상으로 극단적인 결과가 나올 확률이다. p-value가 α(흔히 0.05)보다 작으면 H0을 **기각**한다 — 예로 p=0.01<0.05면 H0 기각. p-value는 'H0이 참일 확률'이 아님에 주의한다."}],"code":{"c":"# p-value < α  → H0 기각\n# 예: p = 0.01, α = 0.05 → 기각\n# 1종 오류: 참인 H0을 기각 (거짓 양성)\n# 2종 오류: 거짓인 H0을 채택 (거짓 음성)","cap":"p<α면 H0 기각, α는 1종 오류 허용 수준"},"key":["H0=효과 없음, H1=효과 있음","p-value<α면 H0 기각 (α는 흔히 0.05)","p-value는 'H0이 참일 확률'이 아니다","1종 오류=참 H0 기각, 2종 오류=거짓 H0 못 기각; 상관≠인과"]}}]},{"t":"표본분포와 중심극한정리","l":[{"t":"모수·통계량·표집분포","q":[{"t":"choice","k":"표집분포 정의","q":"표본평균의 표집분포(sampling distribution)란 무엇인가?","ex":"표집분포는 '통계량의 분포'입니다. 한 표본 내부 값들의 분포(표본분포)나 모집단 분포와 혼동하기 쉽지만, 반복 표집으로 얻은 x̄들의 분포를 가리킵니다.","o":["한 표본 안에 들어 있는 개별 값들의 분포","모집단 전체 값들의 분포","같은 크기의 표본을 반복해서 뽑았을 때 표본평균들이 이루는 분포","데이터를 정규화한 뒤의 분포"],"a":2},{"t":"input","k":"표준오차 계산","q":"모표준편차 σ = 20인 모집단에서 크기 n = 100의 표본을 뽑았다. 표본평균의 표준오차는? (숫자만)","ex":"SE = σ/√n = 20/√100 = 20/10 = 2 입니다. 데이터의 산포(20)보다 평균의 산포(2)가 훨씬 작다는 점이 핵심입니다.","code":"sigma = 20\nn = 100\nse = sigma / (n ** 0.5)","a":["2","2.0","2점0"]},{"t":"choice","k":"표준편차 vs 표준오차","q":"표준편차(SD)와 표준오차(SE)의 차이로 옳은 것은?","ex":"SD는 데이터 자체의 산포이고 SE는 추정치의 산포입니다. n이 커지면 SE는 작아지지만 모집단의 SD는 표본크기와 무관하게 그대로입니다.","o":["SD는 개별 관측값이 흩어진 정도, SE는 표본평균이라는 추정치가 흩어진 정도다","SD와 SE는 같은 값이며 표기만 다르다","SE는 표본이 커질수록 커지고 SD는 작아진다","SD는 항상 SE보다 작다"],"a":0},{"t":"choice","k":"모수 vs 통계량","q":"전국 사용자 전체의 평균 체류시간 μ와, 무작위로 뽑은 1000명의 평균 체류시간 x̄에 대한 설명으로 옳은 것은?","ex":"모집단의 참값인 μ는 (우리가 모를 뿐) 고정된 상수이고, 표본에서 계산하는 x̄은 어떤 표본을 뽑느냐에 따라 달라지는 확률변수입니다. 이 구분이 표집분포 개념의 출발점입니다.","o":["μ는 통계량이고 x̄은 모수다","μ는 모수로 고정된 값이고, x̄은 표본마다 달라지는 통계량이다","μ와 x̄은 표본이 커지면 정의상 같은 값이 된다","둘 다 표본에서 계산되므로 모두 통계량이다"],"a":1},{"t":"choice","k":"표본마다 달라짐","q":"같은 모집단에서 크기 100의 표본을 세 번 뽑았더니 평균이 각각 49.2, 51.4, 50.1이 나왔다. 가장 적절한 해석은?","ex":"표본이 달라지면 x̄도 달라지는 것이 정상이며, 그 흔들림의 크기를 정량화한 값이 표준오차입니다. 버그나 편향이 아니라 표집 변동입니다.","o":["측정 장비나 코드에 버그가 있다는 신호다","모평균이 실험 중에 변했다는 뜻이다","무작위 표집에서 자연스럽게 생기는 표본오차이며, 그 변동 폭이 표준오차로 요약된다","표본이 편향되었으므로 데이터를 버려야 한다"],"a":2}],"th":{"sum":"표본에서 계산한 통계량도 표본마다 달라지는 확률변수이고, 그 분포를 표집분포라고 한다. 중심극한정리는 표본크기가 커질수록 표본평균의 표집분포가 정규분포에 가까워진다고 말한다.","body":[{"h":"모수와 통계량, 그리고 표집분포","t":"모집단의 참값인 모수(μ, σ)는 보통 알 수 없고, 우리는 표본에서 계산한 통계량(x̄, s)으로 추정한다. 표본을 다시 뽑으면 x̄은 조금씩 달라지는데 이 변동을 표본오차라고 부른다. 같은 크기의 표본을 반복해서 뽑았을 때 x̄이 만들어 내는 분포가 바로 **표집분포**(sampling distribution)다."},{"h":"표준오차 SE = σ/√n","t":"표본평균의 표집분포는 평균이 모평균 μ와 같고 표준편차는 σ/√n이다. 이 σ/√n을 **표준오차**(standard error)라 하며, 데이터 자체의 산포인 표준편차 σ와는 다른 개념이다. 분모에 √n이 있으므로 추정의 정밀도를 2배로 올리려면 표본을 4배로 늘려야 한다."},{"h":"CLT가 말하는 것과 말하지 않는 것","t":"중심극한정리는 n이 충분히 크면 모집단 분포 모양과 관계없이 표본평균의 표집분포가 근사 정규분포를 따른다는 정리다. 원본 데이터가 정규분포로 바뀌는 것이 아니라 '평균의 분포'가 정규에 가까워지는 것이다. 모집단이 심하게 치우쳐 있거나 꼬리가 두꺼우면 같은 근사를 얻기 위해 더 큰 n이 필요하다."}],"code":{"c":"import numpy as np\nrng = np.random.default_rng(0)\npop = rng.exponential(1.0, 1_000_000)   # 오른쪽으로 크게 치우친 모집단\nmeans = [rng.choice(pop, 50).mean() for _ in range(5000)]\nprint(round(float(np.std(means)), 3))  # 약 sigma / sqrt(50)","cap":"치우친 모집단이라도 표본평균 5000개의 분포는 종 모양에 가까워지고, 그 산포는 σ/√n에 근접한다."},"key":["표준오차 SE = σ/√n — 오차를 절반으로 줄이려면 표본은 4배 필요","CLT는 원본 데이터가 아니라 '표본평균의 분포'를 정규에 가깝게 만든다","표준편차는 데이터의 산포, 표준오차는 추정치의 산포"]}},{"t":"표준오차와 표본크기의 관계","q":[{"t":"input","k":"n 4배","q":"표본크기를 100에서 400으로 늘리면 표준오차는 원래의 몇 배가 되는가? (숫자만, 예: 0.5)","ex":"SE는 √n에 반비례합니다. n이 4배가 되면 √n은 2배가 되므로 SE는 1/2배로 줄어듭니다.","a":["0.5","0.5배","1/2","절반"]},{"t":"choice","k":"오차 절반","q":"현재 표준오차를 절반으로 줄이고 싶다. 표본크기는 몇 배로 늘려야 하는가?","ex":"SE ∝ 1/√n 이므로 SE를 1/2로 만들려면 √n을 2배, 즉 n을 4배로 늘려야 합니다. 정밀도 개선 비용이 제곱으로 커진다는 뜻입니다.","o":["2배","4배","8배","16배"],"a":1},{"t":"input","k":"SE 계산2","q":"σ = 12, n = 36일 때 표본평균의 표준오차는? (숫자만)","ex":"SE = 12/√36 = 12/6 = 2 입니다.","code":"sigma = 12\nn = 36\nse = sigma / (n ** 0.5)","a":["2","2.0"]},{"t":"choice","k":"n과 무관한 것","q":"표본크기 n을 크게 늘렸을 때, 기대적으로 줄어들지 않는 것은?","ex":"모집단 표준편차 σ는 모집단의 성질이므로 표본을 아무리 늘려도 변하지 않습니다. 줄어드는 것은 추정치의 불확실성(SE, 구간 폭)입니다.","o":["표본평균의 표준오차","표본평균 추정의 신뢰구간 폭","모집단의 표준편차 σ","표집분포의 산포"],"a":2},{"t":"choice","k":"비용 판단","q":"표준오차 4.0을 1.0으로 줄이려면 현재 표본 1000개에서 몇 개까지 모아야 하는가?","ex":"SE를 1/4로 줄이려면 n을 4² = 16배로 늘려야 하므로 1000 × 16 = 16000개가 필요합니다.","o":["4000개","8000개","16000개","40000개"],"a":2},{"t":"choice","k":"표집분포 모양","q":"동일한 모집단에서 n = 10인 표집분포와 n = 1000인 표집분포를 비교하면?","ex":"표본평균은 어느 n에서도 μ를 중심으로 하는 불편추정량이고, 산포만 σ/√n으로 줄어듭니다. 즉 중심은 그대로, 폭만 좁아집니다.","o":["둘 다 중심은 μ 근처지만 n = 1000 쪽이 훨씬 좁다","n = 1000 쪽의 중심이 더 오른쪽으로 이동한다","n = 10 쪽이 더 좁다","표본크기는 표집분포 모양과 관계없다"],"a":0}],"th":{"sum":"표본에서 계산한 통계량도 표본마다 달라지는 확률변수이고, 그 분포를 표집분포라고 한다. 중심극한정리는 표본크기가 커질수록 표본평균의 표집분포가 정규분포에 가까워진다고 말한다.","body":[{"h":"모수와 통계량, 그리고 표집분포","t":"모집단의 참값인 모수(μ, σ)는 보통 알 수 없고, 우리는 표본에서 계산한 통계량(x̄, s)으로 추정한다. 표본을 다시 뽑으면 x̄은 조금씩 달라지는데 이 변동을 표본오차라고 부른다. 같은 크기의 표본을 반복해서 뽑았을 때 x̄이 만들어 내는 분포가 바로 **표집분포**(sampling distribution)다."},{"h":"표준오차 SE = σ/√n","t":"표본평균의 표집분포는 평균이 모평균 μ와 같고 표준편차는 σ/√n이다. 이 σ/√n을 **표준오차**(standard error)라 하며, 데이터 자체의 산포인 표준편차 σ와는 다른 개념이다. 분모에 √n이 있으므로 추정의 정밀도를 2배로 올리려면 표본을 4배로 늘려야 한다."},{"h":"CLT가 말하는 것과 말하지 않는 것","t":"중심극한정리는 n이 충분히 크면 모집단 분포 모양과 관계없이 표본평균의 표집분포가 근사 정규분포를 따른다는 정리다. 원본 데이터가 정규분포로 바뀌는 것이 아니라 '평균의 분포'가 정규에 가까워지는 것이다. 모집단이 심하게 치우쳐 있거나 꼬리가 두꺼우면 같은 근사를 얻기 위해 더 큰 n이 필요하다."}],"code":{"c":"import numpy as np\nrng = np.random.default_rng(0)\npop = rng.exponential(1.0, 1_000_000)   # 오른쪽으로 크게 치우친 모집단\nmeans = [rng.choice(pop, 50).mean() for _ in range(5000)]\nprint(round(float(np.std(means)), 3))  # 약 sigma / sqrt(50)","cap":"치우친 모집단이라도 표본평균 5000개의 분포는 종 모양에 가까워지고, 그 산포는 σ/√n에 근접한다."},"key":["표준오차 SE = σ/√n — 오차를 절반으로 줄이려면 표본은 4배 필요","CLT는 원본 데이터가 아니라 '표본평균의 분포'를 정규에 가깝게 만든다","표준편차는 데이터의 산포, 표준오차는 추정치의 산포"]}},{"t":"중심극한정리의 조건과 오해","q":[{"t":"choice","k":"CLT 정확한 서술","q":"중심극한정리(CLT)에 대한 올바른 설명은?","ex":"CLT의 주어는 '표본평균의 표집분포'입니다. 원본 데이터는 여전히 원래 모양대로 치우쳐 있고, 정규에 가까워지는 것은 평균들의 분포입니다.","o":["표본크기가 커지면 원본 데이터의 분포가 정규분포로 변한다","표본크기가 커지면 표본평균의 표집분포가 근사 정규분포를 따른다","모집단이 정규분포일 때만 표본평균을 쓸 수 있다는 정리다","표본크기가 커지면 모든 통계량의 분산이 0이 된다"],"a":1},{"t":"choice","k":"CLT 예외","q":"다음 중 표본평균에 대한 CLT 근사가 잘 작동하지 않는 상황은?","ex":"CLT는 독립(또는 약한 종속)과 유한 분산을 전제로 합니다. 강한 자기상관이 있으면 유효표본크기가 실제보다 훨씬 작아져 표준오차를 과소평가하게 됩니다.","o":["모집단이 이산형(0/1)인 경우","모집단이 균등분포인 경우","관측치들이 서로 독립이 아니고 강하게 자기상관된 시계열인 경우","표본크기가 10000인 경우"],"a":2},{"t":"input","k":"용어","q":"표본평균의 표집분포가 갖는 표준편차, 즉 σ/√n을 부르는 한국어 용어는? (4글자)","ex":"σ/√n을 표준오차(standard error)라고 합니다. 신뢰구간과 검정통계량 계산의 기본 단위가 되는 값입니다.","a":["표준오차","표준 오차","standard error"]},{"t":"choice","k":"치우친 모집단","q":"모집단이 오른쪽으로 심하게 치우쳐 있을 때(예: 결제 금액) CLT 근사에 대한 설명으로 옳은 것은?","ex":"CLT는 분산이 유한하면 성립하지만 수렴 속도는 분포 모양에 따라 다릅니다. 왜도가 크면 n = 30 정도로는 부족하고 훨씬 큰 표본이 필요할 수 있습니다.","o":["치우침이 심할수록 근사에 필요한 n이 커진다","치우친 모집단에는 CLT가 전혀 적용되지 않는다","치우침이 심할수록 더 작은 n으로도 충분하다","치우침 여부는 필요한 n과 아무 관련이 없다"],"a":0},{"t":"choice","k":"CLT 효용","q":"CLT가 실무에서 유용한 가장 큰 이유는?","ex":"모집단 분포 형태를 몰라도 평균에 대한 추론이 가능해지는 것이 CLT의 실용적 가치입니다. 그래서 A/B 테스트의 지표 비교가 대개 정규 근사로 다뤄집니다.","o":["모집단 분포를 몰라도 표본평균에 대한 구간추정과 검정을 정규 근사로 수행할 수 있기 때문","이상치를 자동으로 제거해 주기 때문","표본을 뽑지 않고도 모평균을 알 수 있기 때문","데이터를 정규분포로 변환해 주기 때문"],"a":0},{"t":"choice","k":"작은 표본","q":"n = 5인 아주 작은 표본에서 치우친 모집단의 평균을 검정하려 한다. 가장 적절한 판단은?","ex":"CLT는 '큰 n'에 대한 극한 결과입니다. n이 매우 작고 모집단이 치우쳐 있으면 부트스트랩이나 순위 기반 비모수 검정이 더 안전합니다.","o":["CLT 덕분에 어떤 n에서도 정규 근사가 성립하므로 그대로 z검정을 쓴다","정규 근사가 위태로우므로 비모수 검정이나 부트스트랩 같은 대안을 고려한다","표본이 작을수록 근사가 좋아지므로 문제없다","표본평균 대신 표본합을 쓰면 근사가 항상 성립한다"],"a":1}],"th":{"sum":"표본에서 계산한 통계량도 표본마다 달라지는 확률변수이고, 그 분포를 표집분포라고 한다. 중심극한정리는 표본크기가 커질수록 표본평균의 표집분포가 정규분포에 가까워진다고 말한다.","body":[{"h":"모수와 통계량, 그리고 표집분포","t":"모집단의 참값인 모수(μ, σ)는 보통 알 수 없고, 우리는 표본에서 계산한 통계량(x̄, s)으로 추정한다. 표본을 다시 뽑으면 x̄은 조금씩 달라지는데 이 변동을 표본오차라고 부른다. 같은 크기의 표본을 반복해서 뽑았을 때 x̄이 만들어 내는 분포가 바로 **표집분포**(sampling distribution)다."},{"h":"표준오차 SE = σ/√n","t":"표본평균의 표집분포는 평균이 모평균 μ와 같고 표준편차는 σ/√n이다. 이 σ/√n을 **표준오차**(standard error)라 하며, 데이터 자체의 산포인 표준편차 σ와는 다른 개념이다. 분모에 √n이 있으므로 추정의 정밀도를 2배로 올리려면 표본을 4배로 늘려야 한다."},{"h":"CLT가 말하는 것과 말하지 않는 것","t":"중심극한정리는 n이 충분히 크면 모집단 분포 모양과 관계없이 표본평균의 표집분포가 근사 정규분포를 따른다는 정리다. 원본 데이터가 정규분포로 바뀌는 것이 아니라 '평균의 분포'가 정규에 가까워지는 것이다. 모집단이 심하게 치우쳐 있거나 꼬리가 두꺼우면 같은 근사를 얻기 위해 더 큰 n이 필요하다."}],"code":{"c":"import numpy as np\nrng = np.random.default_rng(0)\npop = rng.exponential(1.0, 1_000_000)   # 오른쪽으로 크게 치우친 모집단\nmeans = [rng.choice(pop, 50).mean() for _ in range(5000)]\nprint(round(float(np.std(means)), 3))  # 약 sigma / sqrt(50)","cap":"치우친 모집단이라도 표본평균 5000개의 분포는 종 모양에 가까워지고, 그 산포는 σ/√n에 근접한다."},"key":["표준오차 SE = σ/√n — 오차를 절반으로 줄이려면 표본은 4배 필요","CLT는 원본 데이터가 아니라 '표본평균의 분포'를 정규에 가깝게 만든다","표준편차는 데이터의 산포, 표준오차는 추정치의 산포"]}}]},{"t":"신뢰구간 제대로 읽기 (중급)","l":[{"t":"신뢰구간 만들기","q":[{"t":"choice","k":"CI 공식","q":"모평균에 대한 95% 신뢰구간(정규 근사)의 형태로 옳은 것은?","ex":"임계값에 곱하는 것은 데이터의 산포 σ가 아니라 추정치의 산포인 표준오차 σ/√n입니다. 중심은 알 수 없는 μ가 아니라 관측된 x̄입니다.","o":["x̄ ± 1.96 × σ","x̄ ± 1.96 × (σ/√n)","x̄ ± 0.95 × (σ/√n)","μ ± 1.96 × (σ/√n)"],"a":1},{"t":"input","k":"SE 구하기","q":"x̄ = 100, σ = 15, n = 225일 때 표준오차는? (숫자만)","ex":"SE = 15/√225 = 15/15 = 1 입니다. 따라서 95% 신뢰구간은 약 100 ± 1.96, 즉 [98.04, 101.96]이 됩니다.","code":"sigma, n = 15, 225\nse = sigma / (n ** 0.5)","a":["1","1.0"]},{"t":"choice","k":"t vs z","q":"모표준편차 σ를 모르고 표본크기가 15로 작을 때 신뢰구간에 쓸 분포는?","ex":"σ 대신 표본표준편차 s를 쓰면 추가 불확실성이 생겨 꼬리가 두꺼운 t 분포를 씁니다. 자유도는 n − 1 = 14입니다.","o":["표준정규분포(z)","자유도 14인 t 분포","자유도 15인 카이제곱분포","이항분포"],"a":1},{"t":"choice","k":"신뢰수준 낮추기","q":"같은 데이터에서 신뢰수준만 95%에서 90%로 낮추면 구간은?","ex":"요구하는 확신 수준이 낮아지면 임계값(1.96 → 1.645)이 작아져 구간이 좁아집니다. 좁은 구간이 더 좋은 추정이라는 뜻은 아닙니다.","o":["넓어진다","좁아진다","변하지 않는다","좌우로 이동하지만 폭은 같다"],"a":1},{"t":"choice","k":"99% 임계값","q":"신뢰수준을 95%에서 99%로 높이면 정규 근사 임계값은 어떻게 바뀌는가?","ex":"더 높은 확신을 요구할수록 더 넓게 잡아야 하므로 임계값이 커집니다(90%≈1.645, 95%≈1.96, 99%≈2.576).","o":["약 1.96에서 약 2.576으로 커진다","약 1.96에서 약 1.645로 작아진다","1.96 그대로 유지된다","약 1.96에서 약 0.99로 작아진다"],"a":0}],"th":{"sum":"신뢰구간은 점추정치에 불확실성의 폭을 붙인 것이다. '95%'는 이미 계산된 구간 하나에 대한 확률이 아니라, 구간을 만드는 절차의 장기적 성공률을 뜻한다.","body":[{"h":"구간의 구조: 추정치 ± 임계값 × 표준오차","t":"모평균의 신뢰구간은 `x̄ ± 임계값 × SE` 형태다. 정규 근사에서 95%의 임계값은 약 1.96이고, 99%로 올리면 약 2.576, 90%로 낮추면 약 1.645다. σ를 모르고 표본이 작으면 z 대신 자유도 n−1의 t 분포 임계값을 쓴다."},{"h":"95%의 진짜 의미","t":"같은 방식으로 표본을 뽑고 구간을 계산하는 일을 무한히 반복하면 그렇게 만들어진 구간들 중 약 95%가 참인 모수를 포함한다. 빈도주의에서 모수는 고정된 값이고 랜덤한 것은 구간이므로 '**이 구간** 안에 모수가 있을 확률이 95%'라는 표현은 정확하지 않다. 이미 계산이 끝난 하나의 구간은 모수를 포함하거나 포함하지 않거나 둘 중 하나다."},{"h":"폭을 좌우하는 것들","t":"구간 폭은 표준오차와 신뢰수준에 비례한다. 표본을 키우면 √n에 반비례해 좁아지고, 신뢰수준을 높이면 넓어진다. 차이에 대한 신뢰구간이 0을 포함하는지 여부는 같은 유의수준의 양측검정 결과와 대응하므로, p값 하나보다 훨씬 많은 정보를 준다."}],"code":{"c":"import math\nxbar, sigma, n = 50.0, 20.0, 100\nse = sigma / math.sqrt(n)              # 2.0\nlo, hi = xbar - 1.96 * se, xbar + 1.96 * se\nprint(round(se, 2), round(lo, 2), round(hi, 2))   # 2.0 46.08 53.92","cap":"표본평균 50, σ=20, n=100일 때 95% 신뢰구간은 약 [46.08, 53.92]다."},"key":["95% CI는 '절차의 장기 성공률 95%'이지 '이 구간에 모수가 있을 확률 95%'가 아니다","신뢰수준을 높이면 구간은 넓어지고, 표본을 4배로 키우면 폭은 절반이 된다","차이의 신뢰구간이 0을 포함하지 않으면 대응하는 양측검정에서 유의하다"]}},{"t":"95%의 올바른 해석","q":[{"t":"choice","k":"구간 겹침","q":"A군과 B군 각각의 95% 신뢰구간이 조금 겹쳤다. 옳은 결론은?","ex":"개별 구간이 겹쳐도 차이에 대한 검정은 유의할 수 있습니다. 비교의 대상은 '차이'이므로 차이의 신뢰구간을 직접 계산하는 것이 옳습니다.","o":["구간이 겹쳤으므로 두 집단의 차이는 반드시 유의하지 않다","구간이 겹쳤으므로 두 집단은 통계적으로 동일하다","각 군의 구간 겹침만으로는 판단할 수 없고, 차이 자체의 신뢰구간이나 검정을 봐야 한다","구간이 겹치면 표본크기를 줄여야 한다"],"a":2},{"t":"input","k":"랜덤한 대상","q":"빈도주의 신뢰구간 해석에서, 표본마다 달라지는 '랜덤한 대상'은 모수인가 구간인가? (둘 중 하나)","ex":"모수는 고정되어 있고 구간이 표본에 따라 움직입니다. 그래서 '구간이 모수를 덮을 확률'이라는 표현이 올바른 서술입니다.","a":["구간","신뢰구간","interval","구간이다"]},{"t":"choice","k":"데이터 95% 오해","q":"'95% 신뢰구간 안에 전체 데이터의 95%가 들어간다'는 설명이 틀린 이유는?","ex":"개별 값의 95%를 담는 구간은 예측구간(prediction interval)이며 신뢰구간보다 훨씬 넓습니다. 신뢰구간은 σ/√n 스케일이라 n이 커질수록 오히려 좁아집니다.","o":["신뢰구간은 개별 관측값이 아니라 모수(예: 평균)의 위치에 대한 구간이기 때문","신뢰구간은 항상 데이터 범위보다 넓기 때문","데이터가 정규분포일 때만 성립하기 때문","95%가 아니라 68%가 맞기 때문"],"a":0},{"t":"choice","k":"확률 오해","q":"'이 95% 신뢰구간 안에 모평균이 있을 확률은 95%다'라는 말이 빈도주의 관점에서 부정확한 이유는?","ex":"빈도주의에서 확률은 반복 가능한 절차에 붙습니다. μ는 상수이고 구간이 랜덤이므로, 확률 진술의 주어는 구간이어야 합니다. (모수에 확률을 부여하려면 베이지안의 신용구간이 필요합니다.)","o":["신뢰수준이 실제로는 90%이기 때문","모평균은 고정된 상수이므로 이미 계산된 구간은 포함하거나 포함하지 않거나 둘 중 하나이기 때문","확률은 0 또는 1만 가질 수 있기 때문","표본이 정규분포가 아니기 때문"],"a":1},{"t":"choice","k":"올바른 해석","q":"평균 전환율 차이에 대한 95% 신뢰구간이 [0.4%p, 2.6%p]로 나왔다. 이에 대한 올바른 해석은?","ex":"신뢰수준은 '절차의 장기 적중률'입니다. 모수는 고정, 구간은 표본마다 달라지는 랜덤 대상이라는 점이 핵심입니다.","o":["참인 차이가 이 구간 안에 있을 확률이 정확히 95%다","관측된 사용자 중 95%의 전환율 차이가 이 구간 안에 있다","같은 방식으로 실험과 구간 계산을 반복하면 그렇게 만들어진 구간들의 약 95%가 참인 차이를 포함한다","이 실험을 다시 하면 95% 확률로 같은 구간이 나온다"],"a":2},{"t":"choice","k":"0 포함","q":"두 그룹 차이의 95% 신뢰구간이 [-0.3%p, 1.9%p]로 0을 포함했다. 가장 적절한 결론은?","ex":"0을 포함한다는 것은 '효과 없음을 배제하지 못한다'는 뜻이지 '효과가 없다'는 증명이 아닙니다. 구간이 넓다면 아직 결론을 내릴 정보가 부족한 것입니다.","o":["차이가 0이라는 것이 증명되었다","유의수준 5% 양측검정에서 유의하지 않으며, 데이터가 효과 없음부터 +1.9%p까지와 양립한다","실험이 실패했으므로 데이터를 버려야 한다","표본을 줄여 구간을 좁혀야 한다"],"a":1}],"th":{"sum":"신뢰구간은 점추정치에 불확실성의 폭을 붙인 것이다. '95%'는 이미 계산된 구간 하나에 대한 확률이 아니라, 구간을 만드는 절차의 장기적 성공률을 뜻한다.","body":[{"h":"구간의 구조: 추정치 ± 임계값 × 표준오차","t":"모평균의 신뢰구간은 `x̄ ± 임계값 × SE` 형태다. 정규 근사에서 95%의 임계값은 약 1.96이고, 99%로 올리면 약 2.576, 90%로 낮추면 약 1.645다. σ를 모르고 표본이 작으면 z 대신 자유도 n−1의 t 분포 임계값을 쓴다."},{"h":"95%의 진짜 의미","t":"같은 방식으로 표본을 뽑고 구간을 계산하는 일을 무한히 반복하면 그렇게 만들어진 구간들 중 약 95%가 참인 모수를 포함한다. 빈도주의에서 모수는 고정된 값이고 랜덤한 것은 구간이므로 '**이 구간** 안에 모수가 있을 확률이 95%'라는 표현은 정확하지 않다. 이미 계산이 끝난 하나의 구간은 모수를 포함하거나 포함하지 않거나 둘 중 하나다."},{"h":"폭을 좌우하는 것들","t":"구간 폭은 표준오차와 신뢰수준에 비례한다. 표본을 키우면 √n에 반비례해 좁아지고, 신뢰수준을 높이면 넓어진다. 차이에 대한 신뢰구간이 0을 포함하는지 여부는 같은 유의수준의 양측검정 결과와 대응하므로, p값 하나보다 훨씬 많은 정보를 준다."}],"code":{"c":"import math\nxbar, sigma, n = 50.0, 20.0, 100\nse = sigma / math.sqrt(n)              # 2.0\nlo, hi = xbar - 1.96 * se, xbar + 1.96 * se\nprint(round(se, 2), round(lo, 2), round(hi, 2))   # 2.0 46.08 53.92","cap":"표본평균 50, σ=20, n=100일 때 95% 신뢰구간은 약 [46.08, 53.92]다."},"key":["95% CI는 '절차의 장기 성공률 95%'이지 '이 구간에 모수가 있을 확률 95%'가 아니다","신뢰수준을 높이면 구간은 넓어지고, 표본을 4배로 키우면 폭은 절반이 된다","차이의 신뢰구간이 0을 포함하지 않으면 대응하는 양측검정에서 유의하다"]}},{"t":"구간 폭과 검정의 대응","q":[{"t":"input","k":"폭 1/3","q":"신뢰구간 폭을 지금의 1/3로 줄이려면 표본크기를 몇 배로 늘려야 하는가? (숫자만)","ex":"폭 ∝ 1/√n 이므로 폭을 1/3로 만들려면 √n을 3배, 즉 n을 3² = 9배로 늘려야 합니다.","a":["9","9배"]},{"t":"choice","k":"n과 폭","q":"다른 조건이 같을 때 표본크기를 4배로 늘리면 신뢰구간 폭은?","ex":"폭은 SE = σ/√n에 비례하므로 n이 4배가 되면 √n이 2배, 폭은 절반이 됩니다.","o":["1/4로 줄어든다","1/2로 줄어든다","그대로다","2배로 늘어난다"],"a":1},{"t":"choice","k":"CI와 검정 대응","q":"평균 차이의 95% 신뢰구간이 [1.2, 4.8]로 0을 포함하지 않았다. 유의수준 5% 양측검정 결과는?","ex":"95% 신뢰구간과 유의수준 5% 양측검정은 서로 대응합니다. 구간이 귀무값(0)을 배제하면 검정에서도 기각됩니다.","o":["p &lt; 0.05로 귀무가설을 기각한다","p &gt; 0.05로 기각하지 못한다","신뢰구간과 검정은 서로 무관하므로 알 수 없다","항상 p = 0.05가 된다"],"a":0},{"t":"choice","k":"넓은 구간","q":"효과 추정치의 95% 신뢰구간이 [-12%, +15%]로 매우 넓게 나왔다. 가장 적절한 해석은?","ex":"넓은 구간은 '정보 부족'의 신호입니다. 유의하지 않다는 것과 효과가 없다는 것을 구분해야 하며, 이런 경우 표본을 더 모아야 합니다.","o":["효과가 없다는 강한 증거다","효과가 매우 크다는 증거다","표본이 부족해 결론을 내리기 어렵다 — 큰 개선도 큰 악화도 배제하지 못한다","구간이 넓을수록 추정이 정확하다"],"a":2},{"t":"choice","k":"보고 방식","q":"실험 결과를 보고할 때 p값만 적는 것보다 효과크기와 신뢰구간을 함께 제시하는 이유로 가장 적절한 것은?","ex":"p값은 '유의한가'라는 이분법만 주지만 신뢰구간은 '얼마나, 얼마나 정확히'까지 보여 줍니다. 유의성과 실질적 중요성은 다른 문제입니다.","o":["p값 계산이 부정확하기 때문","신뢰구간은 효과의 크기와 정밀도를 함께 보여 주어 실질적 중요성까지 판단할 수 있기 때문","신뢰구간이 있으면 표본크기를 정하지 않아도 되기 때문","규제상 p값 보고가 금지되어 있기 때문"],"a":1}],"th":{"sum":"신뢰구간은 점추정치에 불확실성의 폭을 붙인 것이다. '95%'는 이미 계산된 구간 하나에 대한 확률이 아니라, 구간을 만드는 절차의 장기적 성공률을 뜻한다.","body":[{"h":"구간의 구조: 추정치 ± 임계값 × 표준오차","t":"모평균의 신뢰구간은 `x̄ ± 임계값 × SE` 형태다. 정규 근사에서 95%의 임계값은 약 1.96이고, 99%로 올리면 약 2.576, 90%로 낮추면 약 1.645다. σ를 모르고 표본이 작으면 z 대신 자유도 n−1의 t 분포 임계값을 쓴다."},{"h":"95%의 진짜 의미","t":"같은 방식으로 표본을 뽑고 구간을 계산하는 일을 무한히 반복하면 그렇게 만들어진 구간들 중 약 95%가 참인 모수를 포함한다. 빈도주의에서 모수는 고정된 값이고 랜덤한 것은 구간이므로 '**이 구간** 안에 모수가 있을 확률이 95%'라는 표현은 정확하지 않다. 이미 계산이 끝난 하나의 구간은 모수를 포함하거나 포함하지 않거나 둘 중 하나다."},{"h":"폭을 좌우하는 것들","t":"구간 폭은 표준오차와 신뢰수준에 비례한다. 표본을 키우면 √n에 반비례해 좁아지고, 신뢰수준을 높이면 넓어진다. 차이에 대한 신뢰구간이 0을 포함하는지 여부는 같은 유의수준의 양측검정 결과와 대응하므로, p값 하나보다 훨씬 많은 정보를 준다."}],"code":{"c":"import math\nxbar, sigma, n = 50.0, 20.0, 100\nse = sigma / math.sqrt(n)              # 2.0\nlo, hi = xbar - 1.96 * se, xbar + 1.96 * se\nprint(round(se, 2), round(lo, 2), round(hi, 2))   # 2.0 46.08 53.92","cap":"표본평균 50, σ=20, n=100일 때 95% 신뢰구간은 약 [46.08, 53.92]다."},"key":["95% CI는 '절차의 장기 성공률 95%'이지 '이 구간에 모수가 있을 확률 95%'가 아니다","신뢰수준을 높이면 구간은 넓어지고, 표본을 4배로 키우면 폭은 절반이 된다","차이의 신뢰구간이 0을 포함하지 않으면 대응하는 양측검정에서 유의하다"]}}]},{"t":"가설검정과 p값 심화","l":[{"t":"귀무가설과 검정 절차","q":[{"t":"input","k":"기각 판정","q":"α = 0.05로 정한 검정에서 p = 0.032가 나왔다. 귀무가설을 기각하는가? (기각 / 기각못함)","ex":"p = 0.032 &lt; 0.05 이므로 유의수준 5%에서 귀무가설을 기각합니다. 다만 이는 '효과가 크다'는 뜻이 아니라 '효과 없음과 잘 맞지 않는다'는 뜻입니다.","a":["기각","기각한다","reject","예"]},{"t":"choice","k":"단측 vs 양측","q":"양측검정과 단측검정에 대한 설명으로 옳은 것은?","ex":"단측검정은 같은 데이터에서 p가 대략 절반이 되므로 결과를 보고 방향을 고르면 사실상 유의수준을 두 배로 쓰는 셈입니다. 방향은 사전 등록되어야 합니다.","o":["단측검정은 방향을 사전에 정한 경우에만 정당하며, 결과를 본 뒤 방향을 고르면 오류율이 부풀려진다","단측검정은 항상 양측검정보다 보수적이다","양측검정은 p값이 단측의 1/2이다","방향은 결과를 보고 정하는 것이 표준 관행이다"],"a":0},{"t":"choice","k":"H0 설정","q":"새 추천 알고리즘이 클릭률을 올렸는지 검정하려 한다. 귀무가설 H0로 적절한 것은?","ex":"귀무가설은 보통 '효과 없음/차이 없음'이라는 보수적 기준선입니다. 검정은 이 기준선을 기각할 만큼 증거가 강한지를 따집니다.","o":["새 알고리즘의 클릭률이 기존보다 높다","새 알고리즘과 기존 알고리즘의 클릭률에 차이가 없다","새 알고리즘의 클릭률이 기존보다 낮다","표본크기가 충분하다"],"a":1},{"t":"choice","k":"α 사전 결정","q":"유의수준 α를 데이터를 본 뒤에 결정하면 생기는 문제는?","ex":"α는 사전에 정해야 검정의 오류율 보장이 의미를 갖습니다. 결과를 보고 기준을 옮기면 유의성이 보장하는 것이 아무것도 남지 않습니다.","o":["계산량이 늘어난다","p값이 음수가 될 수 있다","관측 결과에 맞춰 기준을 바꾸는 셈이라 실제 1종 오류율이 명목값보다 커진다","신뢰구간을 계산할 수 없게 된다"],"a":2},{"t":"choice","k":"검정통계량","q":"검정통계량(예: t값)이 하는 역할로 가장 적절한 것은?","ex":"검정통계량은 대체로 (효과) / (표준오차) 형태입니다. 그 값을 귀무가설 하의 분포와 비교해 극단성의 정도를 p값으로 환산합니다.","o":["표본의 크기를 재는 값이다","관측된 차이를 그 불확실성(표준오차)으로 나눠, 귀무분포 위의 어느 위치인지 재는 값이다","모집단의 평균을 직접 추정한 값이다","p값과 무관한 보조 지표다"],"a":1}],"th":{"sum":"p값은 '귀무가설이 참이라고 가정했을 때, 관측된 것만큼 또는 그보다 더 극단적인 결과가 나올 확률'이다. 귀무가설이 참일 확률도, 효과의 크기도 아니다.","body":[{"h":"검정의 뼈대","t":"먼저 귀무가설 H0(효과 없음)과 대립가설 H1을 세우고 유의수준 α를 **데이터를 보기 전에** 정한다. 데이터로 검정통계량을 계산한 뒤, H0가 참일 때 그 통계량이 관측값 이상으로 극단적일 확률인 p값을 구한다. p < α면 H0를 기각하고, 그렇지 않으면 '기각하지 못한다'고 말한다."},{"h":"p값에 대한 흔한 오해","t":"p = 0.03은 '귀무가설이 참일 확률이 3%'라는 뜻이 아니다. p값은 H0를 조건으로 한 데이터의 확률이지, 데이터를 조건으로 한 가설의 확률이 아니다. 또 p값이 작다고 효과가 크다는 뜻도 아니다 — 표본이 아주 크면 실무적으로 무의미한 차이도 아주 작은 p값을 만든다."},{"h":"기각하지 못함은 참이 아니다","t":"p가 크다는 것은 H0에 반하는 증거가 부족하다는 뜻이지 H0가 옳다는 증명이 아니다. 검정력이 낮은 실험은 실제 효과가 있어도 p를 크게 만든다. 그래서 결론은 p값 하나가 아니라 효과크기와 신뢰구간을 함께 보고 내려야 한다."}],"code":{"c":"from scipy import stats\na = [12.1, 11.8, 12.5, 12.0, 12.3]\nb = [12.4, 12.9, 12.7, 13.1, 12.6]\nt, p = stats.ttest_ind(a, b)\nprint(round(t, 3), round(p, 4))   # 검정통계량과 p값","cap":"두 표본 t검정은 t와 p를 함께 돌려준다 — p만 보지 말고 평균 차이와 신뢰구간도 확인한다."},"key":["p값 = H0가 참일 때 관측값 이상으로 극단적인 결과가 나올 확률","p값은 H0가 참일 확률도 아니고 효과 크기도 아니다","p가 크면 '기각하지 못함'이지 'H0가 참'이라는 증명이 아니다"]}},{"t":"p값의 정의와 흔한 오해","q":[{"t":"choice","k":"p값 분포","q":"귀무가설이 실제로 참인 상황에서 실험을 수없이 반복하면 p값의 분포는?","ex":"H0가 참이면 p값은 균등분포를 따릅니다. 그래서 α = 0.05 기준으로 5%의 실험이 우연히 유의해지며, 이것이 다중검정 문제의 근원입니다.","o":["0 근처에 몰린다","1 근처에 몰린다","항상 0.5가 된다","0과 1 사이의 균등분포에 가깝다"],"a":3},{"t":"input","k":"표현 교정","q":"p값이 유의수준보다 클 때, 통계학적으로 올바른 표현은 '귀무가설을 (   )'이다. 괄호에 들어갈 말은? (한국어)","ex":"'귀무가설을 채택한다'는 표현은 피해야 합니다. 검정은 H0를 지지하는 증거를 제공하지 않고, 다만 기각에 실패했을 뿐입니다.","a":["기각하지 못한다","기각할 수 없다","기각하지 않는다","기각 못한다"]},{"t":"choice","k":"p값 정의","q":"p값의 정확한 정의는?","ex":"p값은 가설의 확률이 아니라 'H0 조건 하에서의 데이터(또는 더 극단적인 데이터)의 확률'입니다. 조건의 방향을 뒤집는 것이 가장 흔한 오해입니다.","o":["귀무가설이 참일 확률","대립가설이 거짓일 확률","귀무가설이 참이라고 가정했을 때, 관측된 것만큼 또는 그보다 더 극단적인 결과가 나올 확률","결과가 우연히 나왔을 확률"],"a":2},{"t":"choice","k":"p=0.03 해석","q":"p = 0.03이 나왔을 때 올바른 해석은?","ex":"나머지 보기들은 모두 p값을 가설이나 재현성의 확률로 뒤집어 읽은 것입니다. p값은 오직 H0를 가정한 데이터의 확률입니다.","o":["귀무가설이 참일 확률이 3%다","효과가 존재할 확률이 97%다","실험을 100번 하면 97번 같은 결론이 나온다","귀무가설이 참이라면 이 정도 이상으로 극단적인 결과가 나올 확률이 3%다"],"a":3},{"t":"choice","k":"큰 p값","q":"p = 0.42가 나왔다. 옳은 해석은?","ex":"증거의 부재는 부재의 증거가 아닙니다. 표본이 작거나 분산이 크면 실제 효과가 있어도 p가 커질 수 있으므로 신뢰구간 폭을 함께 봐야 합니다.","o":["귀무가설이 참임이 입증되었다","효과가 0이라는 것이 확인되었다","귀무가설을 기각할 증거가 부족할 뿐이며, 검정력 부족일 가능성도 남아 있다","실험 데이터가 오염되었다는 뜻이다"],"a":2},{"t":"choice","k":"p와 효과크기","q":"표본 100만 명 실험에서 전환율 차이가 0.02%p인데 p = 0.001로 매우 작게 나왔다. 가장 적절한 결론은?","ex":"표본이 커지면 표준오차가 작아져 사소한 차이도 유의해집니다. 통계적 유의성과 실질적 중요성은 별개이며, 효과크기와 신뢰구간을 함께 봐야 합니다.","o":["p가 매우 작으니 효과도 매우 크다","표본이 크면 p값을 믿을 수 없으므로 무시해야 한다","효과크기가 작으므로 p값 계산이 잘못되었다","통계적으로는 유의하지만 효과크기가 실무적으로 의미 있는 수준인지 따로 판단해야 한다"],"a":3}],"th":{"sum":"p값은 '귀무가설이 참이라고 가정했을 때, 관측된 것만큼 또는 그보다 더 극단적인 결과가 나올 확률'이다. 귀무가설이 참일 확률도, 효과의 크기도 아니다.","body":[{"h":"검정의 뼈대","t":"먼저 귀무가설 H0(효과 없음)과 대립가설 H1을 세우고 유의수준 α를 **데이터를 보기 전에** 정한다. 데이터로 검정통계량을 계산한 뒤, H0가 참일 때 그 통계량이 관측값 이상으로 극단적일 확률인 p값을 구한다. p < α면 H0를 기각하고, 그렇지 않으면 '기각하지 못한다'고 말한다."},{"h":"p값에 대한 흔한 오해","t":"p = 0.03은 '귀무가설이 참일 확률이 3%'라는 뜻이 아니다. p값은 H0를 조건으로 한 데이터의 확률이지, 데이터를 조건으로 한 가설의 확률이 아니다. 또 p값이 작다고 효과가 크다는 뜻도 아니다 — 표본이 아주 크면 실무적으로 무의미한 차이도 아주 작은 p값을 만든다."},{"h":"기각하지 못함은 참이 아니다","t":"p가 크다는 것은 H0에 반하는 증거가 부족하다는 뜻이지 H0가 옳다는 증명이 아니다. 검정력이 낮은 실험은 실제 효과가 있어도 p를 크게 만든다. 그래서 결론은 p값 하나가 아니라 효과크기와 신뢰구간을 함께 보고 내려야 한다."}],"code":{"c":"from scipy import stats\na = [12.1, 11.8, 12.5, 12.0, 12.3]\nb = [12.4, 12.9, 12.7, 13.1, 12.6]\nt, p = stats.ttest_ind(a, b)\nprint(round(t, 3), round(p, 4))   # 검정통계량과 p값","cap":"두 표본 t검정은 t와 p를 함께 돌려준다 — p만 보지 말고 평균 차이와 신뢰구간도 확인한다."},"key":["p값 = H0가 참일 때 관측값 이상으로 극단적인 결과가 나올 확률","p값은 H0가 참일 확률도 아니고 효과 크기도 아니다","p가 크면 '기각하지 못함'이지 'H0가 참'이라는 증명이 아니다"]}},{"t":"1종·2종 오류와 검정력","q":[{"t":"choice","k":"2종 오류","q":"실제로 효과가 있는데 실험에서 유의하지 않다고 결론 내렸다. 이는 무엇인가?","ex":"거짓 음성이 2종 오류(β)입니다. 표본 부족, 큰 분산, 작은 효과크기가 주요 원인입니다.","o":["1종 오류","표본 편향","다중검정 문제","2종 오류"],"a":3},{"t":"choice","k":"1종 오류","q":"1종 오류(Type I error)란?","ex":"1종 오류는 효과가 없는데 있다고 결론 내리는 거짓 양성이며, 그 확률의 상한이 유의수준 α입니다.","o":["실제로는 참인 귀무가설을 기각하는 것","실제로는 거짓인 귀무가설을 기각하지 못하는 것","표본크기를 잘못 계산하는 것","대립가설을 잘못 세우는 것"],"a":0},{"t":"input","k":"검정력 계산","q":"2종 오류 확률 β = 0.2인 실험의 검정력(power)은? (숫자만, 예: 0.9)","ex":"검정력 = 1 − β = 1 − 0.2 = 0.8 입니다. 업계 관행상 80%를 최소 기준으로 삼는 경우가 많습니다.","a":["0.8","0.80","80%","0.8배"]},{"t":"choice","k":"검정력 높이기","q":"검정력을 높이는 방법으로 옳지 않은 것은?","ex":"검출 목표 효과가 작아질수록 필요한 표본은 커지고, 같은 표본에서는 검정력이 떨어집니다. 나머지는 모두 검정력을 올리는 방법입니다.","o":["표본크기를 늘린다","지표의 분산을 줄이는 설계(예: 공변량 보정, 이상치 처리)를 쓴다","검출하려는 최소 효과크기를 더 작게 잡는다","측정 노이즈를 줄인다"],"a":2},{"t":"choice","k":"α와 검정력","q":"다른 조건이 모두 같을 때 유의수준을 0.05에서 0.01로 낮추면?","ex":"기준을 엄격하게 하면 거짓 양성은 줄지만 진짜 효과도 놓치기 쉬워집니다. 거짓 양성과 거짓 음성 사이의 트레이드오프입니다.","o":["1종 오류율은 낮아지고 검정력도 낮아진다","1종 오류율과 검정력이 모두 높아진다","1종 오류율은 낮아지고 검정력은 높아진다","둘 다 변하지 않는다"],"a":0},{"t":"choice","k":"저검정력 함정","q":"검정력이 20%로 매우 낮은 실험에서 유의한 결과가 나왔다. 주의할 점은?","ex":"검정력이 낮으면 우연히 큰 효과가 관측된 표본에서만 유의해지므로 효과가 부풀려집니다(승자의 저주, winner's curse). 재현 실험이 필요합니다.","o":["저검정력 상황에서 유의하게 나온 효과는 크게 과대추정되기 쉽다","저검정력이면 1종 오류율이 0이 된다","검정력이 낮을수록 추정치가 정확해진다","검정력은 결과 해석과 무관하다"],"a":0}],"th":{"sum":"p값은 '귀무가설이 참이라고 가정했을 때, 관측된 것만큼 또는 그보다 더 극단적인 결과가 나올 확률'이다. 귀무가설이 참일 확률도, 효과의 크기도 아니다.","body":[{"h":"검정의 뼈대","t":"먼저 귀무가설 H0(효과 없음)과 대립가설 H1을 세우고 유의수준 α를 **데이터를 보기 전에** 정한다. 데이터로 검정통계량을 계산한 뒤, H0가 참일 때 그 통계량이 관측값 이상으로 극단적일 확률인 p값을 구한다. p < α면 H0를 기각하고, 그렇지 않으면 '기각하지 못한다'고 말한다."},{"h":"p값에 대한 흔한 오해","t":"p = 0.03은 '귀무가설이 참일 확률이 3%'라는 뜻이 아니다. p값은 H0를 조건으로 한 데이터의 확률이지, 데이터를 조건으로 한 가설의 확률이 아니다. 또 p값이 작다고 효과가 크다는 뜻도 아니다 — 표본이 아주 크면 실무적으로 무의미한 차이도 아주 작은 p값을 만든다."},{"h":"기각하지 못함은 참이 아니다","t":"p가 크다는 것은 H0에 반하는 증거가 부족하다는 뜻이지 H0가 옳다는 증명이 아니다. 검정력이 낮은 실험은 실제 효과가 있어도 p를 크게 만든다. 그래서 결론은 p값 하나가 아니라 효과크기와 신뢰구간을 함께 보고 내려야 한다."}],"code":{"c":"from scipy import stats\na = [12.1, 11.8, 12.5, 12.0, 12.3]\nb = [12.4, 12.9, 12.7, 13.1, 12.6]\nt, p = stats.ttest_ind(a, b)\nprint(round(t, 3), round(p, 4))   # 검정통계량과 p값","cap":"두 표본 t검정은 t와 p를 함께 돌려준다 — p만 보지 말고 평균 차이와 신뢰구간도 확인한다."},"key":["p값 = H0가 참일 때 관측값 이상으로 극단적인 결과가 나올 확률","p값은 H0가 참일 확률도 아니고 효과 크기도 아니다","p가 크면 '기각하지 못함'이지 'H0가 참'이라는 증명이 아니다"]}}]},{"t":"상관·인과와 A/B 테스트 설계 (심화)","l":[{"t":"상관, 인과, 교란변수","q":[{"t":"choice","k":"교란변수","q":"여름철 아이스크림 판매량과 익사 사고 건수가 강한 양의 상관을 보인다. 가장 타당한 설명은?","ex":"제3의 변수(기온)가 두 변수 모두에 영향을 주면 둘 사이에 인과가 없어도 상관이 나타납니다. 이것이 전형적인 교란(confounding)입니다.","o":["아이스크림 섭취가 익사 위험을 높인다","익사 사고가 아이스크림 소비를 늘린다","상관계수 계산이 잘못되었다","기온이라는 교란변수가 두 값 모두를 끌어올린다"],"a":3},{"t":"input","k":"역설 이름","q":"그룹별로 보면 모두 A가 우세한데 데이터를 합치면 B가 우세해지는, 집계 수준에 따라 결론이 뒤집히는 현상을 무엇이라 하는가? (한국어 또는 영문)","ex":"심슨의 역설은 교란변수(그룹 구성 비율)를 무시하고 합쳤을 때 생깁니다. 세분화된 지표와 전체 지표가 다를 때는 구성 변화를 먼저 확인해야 합니다.","a":["심슨의 역설","심슨 역설","Simpson's paradox","simpson paradox","심슨의역설"]},{"t":"choice","k":"r=0 의미","q":"두 변수의 피어슨 상관계수가 r = 0으로 나왔다. 올바른 해석은?","ex":"피어슨 상관은 선형 관계의 강도만 잽니다. 대칭적인 이차 관계처럼 뚜렷한 패턴이 있어도 r이 0에 가까울 수 있으므로 산점도를 꼭 봐야 합니다.","o":["두 변수 사이에 어떠한 관계도 없다","두 변수가 서로 독립임이 증명되었다","한 변수가 상수라는 뜻이다","선형 관계가 없다는 뜻이며, U자 같은 비선형 관계는 있을 수 있다"],"a":3},{"t":"choice","k":"역인과","q":"'고객지원 채팅을 많이 이용한 사용자일수록 이탈률이 높다'는 관측에서 가장 먼저 의심할 것은?","ex":"원인과 결과의 시간 순서가 뒤바뀐 해석이 역인과입니다. 이런 관측 데이터로는 방향을 결정할 수 없으므로 실험이나 시점 기반 분석이 필요합니다.","o":["채팅 기능이 사용자를 이탈시킨다","표본크기가 부족하다","상관계수 대신 공분산을 써야 한다","이미 문제를 겪어 이탈 위험이 높은 사용자가 채팅을 이용한다는 역인과 가능성"],"a":3},{"t":"choice","k":"선택 편향","q":"앱 내 팝업 설문에 '응답한 사용자'만으로 만족도를 집계했을 때 생기는 대표적 문제는?","ex":"응답자와 비응답자의 성향이 다르면 표본이 모집단을 대표하지 못합니다. 표본을 아무리 늘려도 편향은 사라지지 않습니다.","o":["응답 의향이 있는 특정 집단만 포함되는 선택 편향","표준오차가 0이 되는 문제","p값이 계산되지 않는 문제","중심극한정리가 성립하지 않는 문제"],"a":0},{"t":"choice","k":"무작위 배정","q":"무작위 배정이 관측 연구보다 강한 인과 근거를 주는 이유는?","ex":"관측 연구는 우리가 아는 변수만 보정할 수 있지만, 무작위 배정은 알지 못하는 변수까지 평균적으로 균형을 맞춥니다.","o":["표본크기를 줄여 주기 때문","p값을 항상 작게 만들기 때문","데이터 수집 비용이 낮기 때문","측정하지 못한 교란변수까지 두 군에 기대적으로 균형 있게 배분되기 때문"],"a":3}],"th":{"sum":"관측 데이터의 상관은 교란변수, 역인과, 선택 편향으로도 생긴다. 무작위 배정과 사전에 확정한 설계가 있어야 인과를 말할 수 있다.","body":[{"h":"상관이 인과가 아닌 이유","t":"X와 Y가 함께 움직이는 데는 X→Y 말고도 Y→X(역인과), 제3의 변수 Z가 둘 모두에 영향을 주는 **교란**(confounding), 표본이 특정 조건으로 걸러진 선택 편향, 그리고 순전한 우연이 있다. 아이스크림 판매량과 익사 사고는 기온이라는 교란변수 때문에 함께 오른다. 또 상관계수 r = 0은 '선형' 관계가 없다는 뜻일 뿐 아무 관계가 없다는 뜻이 아니다."},{"h":"무작위 배정이 하는 일","t":"사용자를 무작위로 A/B에 배정하면 알려진 교란변수뿐 아니라 **측정하지 못한** 교란변수까지 기대적으로 두 군에 균형 있게 나뉜다. 그래서 관측된 차이를 처치 효과로 해석할 수 있다. 배정 비율이 설계와 다르게 나오는 SRM(sample ratio mismatch)이 보이면 결과 해석 전에 실험 파이프라인부터 의심해야 한다."},{"h":"표본크기, 다중검정, 피킹","t":"필요한 표본크기는 검출하려는 최소 효과(MDE)가 작을수록, 지표 분산이 클수록, 요구 검정력이 높을수록 커진다. 지표를 여러 개 보면 우연히 유의한 결과가 생기므로 본페로니(α/m)나 FDR 보정이 필요하다. 유의해질 때까지 결과를 반복해서 들여다보고 멈추는 **피킹**(peeking)은 1종 오류율을 크게 부풀린다."}],"code":{"c":"m = 10                # 동시에 보는 지표 수\nalpha = 0.05\nprint(alpha / m)                        # 본페로니 임계값 = 0.005\nprint(round(1 - (1 - alpha) ** m, 3))   # 보정 없을 때 최소 1개가 유의할 확률","cap":"지표 10개를 α=0.05로 보정 없이 보면, 실제 효과가 전혀 없어도 하나 이상 유의할 확률이 약 40%다."},"key":["무작위 배정만이 측정되지 않은 교란변수까지 균형 맞춰 준다","지표를 m개 보면 보정 없이는 거짓 양성이 급증한다 — 본페로니는 α/m","표본크기를 사전에 확정하고, 유의할 때까지 들여다보는 피킹을 피하라"]}},{"t":"A/B 테스트 설계와 표본크기","q":[{"t":"choice","k":"MDE 절반","q":"다른 조건이 같을 때 검출하려는 최소 효과크기를 절반으로 낮추면 필요한 표본크기는 대략?","ex":"필요 표본은 효과크기의 제곱에 반비례하므로 효과를 1/2로 잡으면 표본은 약 4배가 필요합니다.","o":["절반이 된다","그대로다","2배가 된다","4배가 된다"],"a":3},{"t":"input","k":"SRM 용어","q":"50:50으로 설계한 A/B 실험에서 실제 배정 비율이 52:48로 통계적으로 유의하게 어긋난 상황을 가리키는 용어의 약자는? (영문 3글자)","ex":"SRM(sample ratio mismatch)은 배정·로깅 파이프라인 결함의 신호입니다. SRM이 있으면 결과 해석 전에 원인을 먼저 찾아야 합니다.","a":["SRM","srm","sample ratio mismatch"]},{"t":"choice","k":"표본크기 요인","q":"A/B 테스트에 필요한 표본크기가 커지는 조건은?","ex":"필요 표본은 대략 분산에 비례하고 효과크기의 제곱에 반비례합니다. 미세한 차이를 잡아내려 할수록 비용이 급격히 커집니다.","o":["검출하려는 최소 효과(MDE)를 더 크게 잡을수록","지표의 분산이 작을수록","검출하려는 최소 효과가 작고, 지표 분산이 크고, 요구 검정력이 높을수록","유의수준 α를 크게 잡을수록"],"a":2},{"t":"choice","k":"가드레일 지표","q":"전환율을 올리려는 실험에서 가드레일 지표(guardrail metric)를 함께 보는 이유는?","ex":"목표 지표만 좋아지고 성능이나 사용자 경험이 나빠지는 변경을 걸러 내기 위한 안전장치입니다.","o":["목표 지표의 p값을 낮추기 위해","표본크기를 줄이기 위해","무작위 배정을 대체하기 위해","지연시간, 오류율, 이탈률 같은 지표가 악화되지 않았는지 확인해 국소 최적화의 부작용을 잡기 위해"],"a":3},{"t":"choice","k":"실험 기간","q":"표본크기 요건을 하루 만에 채웠더라도 최소 1~2주를 돌리라고 권하는 이유로 가장 적절한 것은?","ex":"하루치 표본은 특정 요일 사용자만 대표할 수 있습니다. 주기성과 초기의 신기 효과(novelty effect)를 흡수하려면 온전한 주 단위 관측이 안전합니다.","o":["p값이 시간이 지나면 자동으로 작아지기 때문","무작위 배정이 하루 만에는 작동하지 않기 때문","표준오차가 시간에 비례해 커지기 때문","요일·시간대에 따른 사용자 구성 변화(주중/주말 효과)와 신기 효과를 반영하기 위해"],"a":3}],"th":{"sum":"관측 데이터의 상관은 교란변수, 역인과, 선택 편향으로도 생긴다. 무작위 배정과 사전에 확정한 설계가 있어야 인과를 말할 수 있다.","body":[{"h":"상관이 인과가 아닌 이유","t":"X와 Y가 함께 움직이는 데는 X→Y 말고도 Y→X(역인과), 제3의 변수 Z가 둘 모두에 영향을 주는 **교란**(confounding), 표본이 특정 조건으로 걸러진 선택 편향, 그리고 순전한 우연이 있다. 아이스크림 판매량과 익사 사고는 기온이라는 교란변수 때문에 함께 오른다. 또 상관계수 r = 0은 '선형' 관계가 없다는 뜻일 뿐 아무 관계가 없다는 뜻이 아니다."},{"h":"무작위 배정이 하는 일","t":"사용자를 무작위로 A/B에 배정하면 알려진 교란변수뿐 아니라 **측정하지 못한** 교란변수까지 기대적으로 두 군에 균형 있게 나뉜다. 그래서 관측된 차이를 처치 효과로 해석할 수 있다. 배정 비율이 설계와 다르게 나오는 SRM(sample ratio mismatch)이 보이면 결과 해석 전에 실험 파이프라인부터 의심해야 한다."},{"h":"표본크기, 다중검정, 피킹","t":"필요한 표본크기는 검출하려는 최소 효과(MDE)가 작을수록, 지표 분산이 클수록, 요구 검정력이 높을수록 커진다. 지표를 여러 개 보면 우연히 유의한 결과가 생기므로 본페로니(α/m)나 FDR 보정이 필요하다. 유의해질 때까지 결과를 반복해서 들여다보고 멈추는 **피킹**(peeking)은 1종 오류율을 크게 부풀린다."}],"code":{"c":"m = 10                # 동시에 보는 지표 수\nalpha = 0.05\nprint(alpha / m)                        # 본페로니 임계값 = 0.005\nprint(round(1 - (1 - alpha) ** m, 3))   # 보정 없을 때 최소 1개가 유의할 확률","cap":"지표 10개를 α=0.05로 보정 없이 보면, 실제 효과가 전혀 없어도 하나 이상 유의할 확률이 약 40%다."},"key":["무작위 배정만이 측정되지 않은 교란변수까지 균형 맞춰 준다","지표를 m개 보면 보정 없이는 거짓 양성이 급증한다 — 본페로니는 α/m","표본크기를 사전에 확정하고, 유의할 때까지 들여다보는 피킹을 피하라"]}},{"t":"다중검정과 피킹","q":[{"t":"choice","k":"다중검정 직관","q":"실제 효과가 전혀 없는 실험에서 서로 독립인 지표 20개를 α = 0.05로 각각 검정하면 기대되는 '유의' 지표 수는?","ex":"H0가 참이면 각 검정이 유의할 확률이 5%이므로 20 × 0.05 = 1개가 기대됩니다. 지표를 많이 볼수록 우연한 발견이 늘어납니다.","o":["0개","약 1개","약 5개","약 10개"],"a":1},{"t":"input","k":"본페로니","q":"전체 유의수준 α = 0.05를 유지하면서 지표 10개를 동시에 검정할 때, 본페로니 보정 후 각 검정에 적용할 임계값은? (숫자만)","ex":"본페로니 보정은 α/m을 각 검정의 임계값으로 씁니다. 0.05/10 = 0.005 입니다.","code":"alpha = 0.05\nm = 10\nprint(alpha / m)","a":["0.005",".005","0.0050"]},{"t":"choice","k":"본페로니 특성","q":"본페로니 보정의 특징으로 옳은 것은?","ex":"본페로니는 지표 간 상관과 무관하게 family-wise error rate를 통제해 주지만 그만큼 보수적입니다. 지표가 많을 때는 FDR(Benjamini-Hochberg)이 대안이 됩니다.","o":["검정 수가 많아질수록 기준이 느슨해진다","1종 오류율을 전혀 통제하지 못한다","지표들이 독립일 때만 사용할 수 있다","매우 보수적이어서 검정 수가 많으면 검정력이 크게 떨어진다"],"a":3},{"t":"choice","k":"FDR","q":"Benjamini-Hochberg 절차가 통제하는 대상은?","ex":"FDR은 '발견 목록 중 거짓의 비율'을 통제해 본페로니보다 덜 보수적입니다. 탐색적으로 지표를 많이 볼 때 적합합니다.","o":["family-wise error rate(하나라도 거짓 양성이 나올 확률)","2종 오류율","표본 비율 불일치","false discovery rate(유의하다고 선언한 것들 중 거짓 양성의 기대 비율)"],"a":3},{"t":"choice","k":"피킹 해법","q":"실험 도중에도 결과를 계속 모니터링하고 싶다면 통계적으로 올바른 접근은?","ex":"중간 점검을 허용하려면 그에 맞게 유의수준을 배분하는 순차검정 설계가 필요합니다. 지표 수를 줄이는 것은 다중검정 대책이지 피킹 대책이 아닙니다.","o":["그룹 순차검정(알파 소비 함수)이나 항시 유효(always-valid) 신뢰구간 같은 순차적 방법을 사용한다","그냥 매일 보고 p &lt; 0.05가 되면 즉시 종료한다","α를 0.1로 올려 여유를 둔다","지표를 하나만 보면 피킹 문제가 사라진다"],"a":0},{"t":"choice","k":"피킹","q":"실험 결과를 매일 확인하다가 처음으로 p &lt; 0.05가 되는 날 실험을 멈추고 승리를 선언했다. 무엇이 문제인가?","ex":"피킹(peeking)은 여러 시점에 걸친 다중검정과 같습니다. 계속 보다가 유의한 순간에 멈추면 거짓 양성이 크게 늘어납니다.","o":["반복해서 들여다보며 멈출 시점을 고르면 실제 1종 오류율이 명목 5%보다 훨씬 커진다","표본크기가 너무 커져 효과가 과소추정된다","매일 보는 것은 통계적으로 아무 영향이 없다","검정력이 100%가 되어 버린다"],"a":0}],"th":{"sum":"관측 데이터의 상관은 교란변수, 역인과, 선택 편향으로도 생긴다. 무작위 배정과 사전에 확정한 설계가 있어야 인과를 말할 수 있다.","body":[{"h":"상관이 인과가 아닌 이유","t":"X와 Y가 함께 움직이는 데는 X→Y 말고도 Y→X(역인과), 제3의 변수 Z가 둘 모두에 영향을 주는 **교란**(confounding), 표본이 특정 조건으로 걸러진 선택 편향, 그리고 순전한 우연이 있다. 아이스크림 판매량과 익사 사고는 기온이라는 교란변수 때문에 함께 오른다. 또 상관계수 r = 0은 '선형' 관계가 없다는 뜻일 뿐 아무 관계가 없다는 뜻이 아니다."},{"h":"무작위 배정이 하는 일","t":"사용자를 무작위로 A/B에 배정하면 알려진 교란변수뿐 아니라 **측정하지 못한** 교란변수까지 기대적으로 두 군에 균형 있게 나뉜다. 그래서 관측된 차이를 처치 효과로 해석할 수 있다. 배정 비율이 설계와 다르게 나오는 SRM(sample ratio mismatch)이 보이면 결과 해석 전에 실험 파이프라인부터 의심해야 한다."},{"h":"표본크기, 다중검정, 피킹","t":"필요한 표본크기는 검출하려는 최소 효과(MDE)가 작을수록, 지표 분산이 클수록, 요구 검정력이 높을수록 커진다. 지표를 여러 개 보면 우연히 유의한 결과가 생기므로 본페로니(α/m)나 FDR 보정이 필요하다. 유의해질 때까지 결과를 반복해서 들여다보고 멈추는 **피킹**(peeking)은 1종 오류율을 크게 부풀린다."}],"code":{"c":"m = 10                # 동시에 보는 지표 수\nalpha = 0.05\nprint(alpha / m)                        # 본페로니 임계값 = 0.005\nprint(round(1 - (1 - alpha) ** m, 3))   # 보정 없을 때 최소 1개가 유의할 확률","cap":"지표 10개를 α=0.05로 보정 없이 보면, 실제 효과가 전혀 없어도 하나 이상 유의할 확률이 약 40%다."},"key":["무작위 배정만이 측정되지 않은 교란변수까지 균형 맞춰 준다","지표를 m개 보면 보정 없이는 거짓 양성이 급증한다 — 본페로니는 α/m","표본크기를 사전에 확정하고, 유의할 때까지 들여다보는 피킹을 피하라"]}}]},{"t":"시뮬레이션 · 눈으로 보는 코드","l":[{"t":"시뮬레이션 I","q":[{"t":"sim","k":"통계 시뮬레이션","lv":2,"q":"<b>평균과 중앙값의 차이</b>를 보이세요. 이상치 하나를 추가하기 전후의 평균·중앙값을 <code>snap</code> 으로 기록하고 <b>[평균변화, 중앙값변화]</b>를 돌려주세요.","src":"const BASE = [10, 12, 13, 11, 14];\nconst OUTLIER = 1000;\n\nfunction robust() {\n  return [0, 0];\n}\n\nRESULT = robust();","tests":[{"d":"평균이 크게 움직인다","js":"RESULT[0]>100"},{"d":"중앙값은 거의 움직이지 않는다","js":"Math.abs(RESULT[1])<=1"},{"d":"두 장면이 기록된다","js":"FRAMES.length===2"},{"d":"이상치 추가 후 표본 수가 늘어난다","js":"FRAMES[1].opt.n===FRAMES[0].opt.n+1"},{"d":"평균 변화가 중앙값 변화보다 훨씬 크다","js":"RESULT[0]>Math.abs(RESULT[1])*50"}],"ex":"평균은 <b>모든 값의 크기</b>에 반응하고 중앙값은 <b>순위</b>에만 반응합니다. 그래서 값 하나가 평균을 200 가까이 밀어 올려도 중앙값은 거의 그대로입니다. 응답 시간·소득처럼 <b>꼬리가 긴 분포</b>에서는 평균이 대표값 노릇을 못 하므로 중앙값과 <b>백분위(p95·p99)</b>를 함께 봅니다 — 평균 응답 시간만 보고 '괜찮다' 고 판단하는 것이 흔한 실수입니다."},{"t":"sim","k":"통계 시뮬레이션","lv":3,"q":"<b>큰 수의 법칙</b>을 결정적으로 보이세요. 주기적인 수열(1,2,3,4,5,6 반복)의 누적 평균이 참값 3.5 에 수렴하는 과정을 기록하고, <b>600개 시점의 평균</b>을 돌려주세요.","src":"function lln() {\n  let sum = 0;\n  // 여기에 구현하세요 — 100개 단위로 snap 을 부르세요\n  return 0;\n}\n\nRESULT = lln();","tests":[{"d":"600개의 평균은 정확히 3.5 다","js":"RESULT===3.5"},{"d":"6개 시점이 기록된다","js":"FRAMES.length===6"},{"d":"마지막 시점(600)에서 정확히 3.5 다","js":"FRAMES[FRAMES.length-1].value[0]===3.5"},{"d":"모든 시점의 오차가 0.05 이하다","js":"FRAMES.every(f=>f.opt.err<=0.05)"},{"d":"표본 수가 늘어난다","js":"FRAMES.every((f,i)=>i===0||f.opt.n>FRAMES[i-1].opt.n)"}],"ex":"주기 6이 100 을 나누어떨어지지 않아 중간 시점에는 오차가 남았다 사라졌다 하지만(n=100 → 3.46, n=300 → 3.5, n=400 → 3.49) 그 폭은 0.05 를 넘지 않고, 주기가 딱 맞는 n=600 에서 정확히 3.5 가 됩니다 — 오차가 <b>줄어들며 참값에 붙는</b> 것이 큰 수의 법칙입니다. 실제 무작위 표본에서는 오차가 <b>표본 수의 제곱근에 반비례</b>해 줄어듭니다(4배 정확해지려면 16배의 표본). 이 관계가 A/B 테스트에 필요한 표본 수를 정하고, '며칠 돌려야 하는가' 를 계산하는 근거가 됩니다."},{"t":"sim","k":"통계 시뮬레이션","lv":3,"q":"<b>1종·2종 오류</b>를 세어 보세요. 실제 상태와 검정 결과가 주어질 때 각 오류 수를 <code>snap</code> 으로 기록하고 <b>[1종, 2종]</b>을 돌려주세요.","src":"const CASES = [\n  {truth:'null', reject:true},   // 1종\n  {truth:'null', reject:false},\n  {truth:'alt',  reject:false},  // 2종\n  {truth:'alt',  reject:true},\n  {truth:'null', reject:true},   // 1종\n  {truth:'alt',  reject:false}   // 2종\n];\n\nfunction errors() {\n  return [0, 0];\n}\n\nRESULT = errors();","tests":[{"d":"1종 오류는 2번이다","js":"RESULT[0]===2"},{"d":"2종 오류는 2번이다","js":"RESULT[1]===2"},{"d":"사례마다 장면이 기록된다","js":"FRAMES.length===6"},{"d":"정답이 2번 있다","js":"FRAMES.filter(f=>f.opt.kind==='정답').length===2"},{"d":"오류 수가 줄어들지 않는다","js":"FRAMES.every((f,i)=>i===0||(f.value[0]>=FRAMES[i-1].value[0]&&f.value[1]>=FRAMES[i-1].value[1]))"}],"ex":"<b>1종</b>은 아무 일도 없는데 있다고 하는 것(거짓 양성), <b>2종</b>은 있는데 없다고 하는 것(거짓 음성)입니다. 유의수준을 낮추면 1종은 줄지만 2종이 늘어납니다 — <b>어느 쪽 실수가 더 비싼가</b>로 정해야 합니다. 경보 시스템에서 1종이 많으면 <b>사람들이 경보를 무시하게 되고</b>, 2종이 많으면 사고를 놓칩니다. 통계적 검정력(1 − 2종 확률)은 표본 수를 늘려야 올라갑니다."},{"t":"sim","k":"통계 시뮬레이션","lv":4,"q":"<b>다중 비교 문제</b>를 보이세요. 유의수준 0.05 로 지표 20개를 각각 검정할 때, 실제로는 차이가 없어도 <b>적어도 하나가 유의하게 나올 확률</b>을 계산하고, 본페로니 보정 후 확률과 함께 <code>[보정전, 보정후]</code> 로 돌려주세요(소수 셋째 자리).","src":"const M = 20, ALPHA = 0.05;\n\nfunction multiple() {\n  return [0, 0];\n}\n\nRESULT = multiple();","tests":[{"d":"보정 없이는 거짓 양성 확률이 0.6 을 넘는다","js":"RESULT[0]>0.6"},{"d":"본페로니 보정 후에는 0.05 근처로 내려온다","js":"RESULT[1]<0.06"},{"d":"두 장면이 기록된다","js":"FRAMES.length===2"},{"d":"보정된 유의수준이 훨씬 작다","js":"FRAMES[1].opt.alpha<FRAMES[0].opt.alpha"},{"d":"보정이 거짓 양성 확률을 크게 낮춘다","js":"RESULT[0]/RESULT[1]>10"}],"ex":"지표 20개를 각각 5% 수준으로 검정하면, <b>아무 차이가 없어도</b> 적어도 하나가 '유의' 하게 나올 확률이 64% 입니다. 그래서 A/B 테스트에서 지표를 잔뜩 늘어놓고 <b>이긴 것만 보고</b>하면 거의 언제나 승리를 찾을 수 있습니다. 방어는 <b>주 지표를 미리 하나 정하는 것</b>이고, 여러 개를 봐야 한다면 본페로니(α/m)나 FDR 보정을 씁니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 II","q":[{"t":"sim","k":"통계 시뮬레이션","lv":3,"q":"<b>심슨의 역설</b>을 재현하세요. 그룹별로는 A 가 우세한데 합치면 B 가 우세해지는 상황을 계산하고, <b>[A전체, B전체]</b> 비율을 돌려주세요(소수 셋째 자리).","src":"const DATA = {\n  easy: { A: {win:  81, n:  87}, B: {win: 234, n: 270} },\n  hard: { A: {win: 192, n: 263}, B: {win:  55, n:  80} }\n};\n\nfunction simpson() {\n  return [0, 0];\n}\n\nRESULT = simpson();","tests":[{"d":"전체에서는 B 가 우세하다","js":"RESULT[1]>RESULT[0]"},{"d":"쉬운 그룹에서는 A 가 우세하다","js":"FRAMES[0].value[0]>FRAMES[0].value[1]"},{"d":"어려운 그룹에서도 A 가 우세하다","js":"FRAMES[1].value[0]>FRAMES[1].value[1]"},{"d":"세 장면이 기록된다","js":"FRAMES.length===3"},{"d":"모든 비율이 0과 1 사이다","js":"FRAMES.every(f=>f.value.every(v=>v>=0&&v<=1))"}],"ex":"두 그룹 <b>모두에서 A 가 이겼는데</b> 합치면 B 가 이깁니다 — 각 그룹의 표본 구성이 다르기 때문입니다(B 는 쉬운 문제를 많이 풀었습니다). 이것이 <b>합쳐 보는 것이 위험한 이유</b>입니다. 실무에서는 신규/기존 사용자, 모바일/데스크톱처럼 <b>구성이 다른 집단</b>이 섞일 때 자주 나타나므로, A/B 테스트 결과는 <b>세그먼트별로도</b> 확인해야 합니다."},{"t":"sim","k":"통계 시뮬레이션","lv":2,"q":"<b>백분위수</b>를 계산하세요. 응답 시간 배열에서 p50·p95·p99 를 구해 <code>snap</code> 으로 기록하고 <b>[p50, p95, p99]</b> 를 돌려주세요.","src":"const MS = Array.from({length: 100}, (_, i) => i + 1);   // 1~100ms\n\nfunction pct() {\n  return [0, 0, 0];\n}\n\nRESULT = pct();","tests":[{"d":"p50 은 50ms 다","js":"RESULT[0]===50"},{"d":"p95 는 95ms 다","js":"RESULT[1]===95"},{"d":"p99 는 99ms 다","js":"RESULT[2]===99"},{"d":"세 백분위가 기록된다","js":"FRAMES.length===3"},{"d":"백분위가 커질수록 값도 커진다","js":"FRAMES.every((f,i)=>i===0||f.value[0]>FRAMES[i-1].value[0])"}],"ex":"백분위는 <b>정렬한 뒤 위치를 고르는</b> 계산이라 이상치에 강합니다. 성능 논의에서 평균 대신 p95·p99 를 쓰는 이유는, <b>느린 1%가 겪는 경험</b>이 서비스 인상을 좌우하기 때문입니다. 주의할 점 둘: 백분위는 <b>평균을 낼 수 없습니다</b>(여러 서버의 p99 를 평균 내면 무의미) — 원자료나 히스토그램을 합쳐 다시 계산해야 합니다."},{"t":"sim","k":"통계 시뮬레이션","lv":3,"q":"<b>표본 크기와 오차 범위</b>의 관계를 보이세요. 비율 0.5 기준 95% 신뢰구간의 반폭(1.96·√(p(1−p)/n))을 표본 수마다 계산하고, <b>n=10,000 일 때의 반폭</b>을 돌려주세요(소수 넷째 자리).","src":"const NS = [100, 400, 1600, 10000];\n\nfunction margin() {\n  return 0;\n}\n\nRESULT = margin();","tests":[{"d":"n=10,000 의 반폭은 약 0.0098 이다","js":"Math.abs(RESULT-0.0098)<0.0002"},{"d":"네 개의 표본 크기가 기록된다","js":"FRAMES.length===4"},{"d":"표본이 커지면 오차가 줄어든다","js":"FRAMES.every((f,i)=>i===0||f.value[0]<FRAMES[i-1].value[0])"},{"d":"표본을 4배로 늘리면 오차가 절반이 된다","js":"Math.abs(FRAMES[0].value[0]/FRAMES[1].value[0]-2)<0.05"},{"d":"모든 반폭이 0보다 크다","js":"FRAMES.every(f=>f.value[0]>0)"}],"ex":"검사가 확인하는 <b>4배 → 절반</b> 관계가 핵심입니다 — 오차는 <code>1/√n</code> 로 줄어듭니다. 그래서 정확도를 두 배로 올리려면 <b>표본을 네 배</b> 모아야 하고, 이것이 A/B 테스트가 생각보다 오래 걸리는 이유입니다. 반대로 말하면 표본 100개로 얻은 결론의 오차는 ±10%p 수준이라, <b>작은 차이는 판별할 수 없습니다</b> — 실험 전에 필요한 표본 수를 계산해야 하는 이유입니다."},{"t":"sim","k":"통계 시뮬레이션","lv":4,"q":"<b>조기 종료의 위험</b>(peeking)을 보이세요. 검정을 매일 확인하며 유의하면 멈출 때, 5일 동안의 <b>누적 거짓 양성 확률</b>을 계산하고 마지막 값을 돌려주세요(소수 셋째 자리, 각 확인은 독립으로 가정).","src":"const DAYS = 5, ALPHA = 0.05;\n\nfunction peeking() {\n  return 0;\n}\n\nRESULT = peeking();","tests":[{"d":"5일 누적 거짓 양성 확률은 약 0.226 이다","js":"Math.abs(RESULT-0.226)<0.002"},{"d":"날마다 장면이 기록된다","js":"FRAMES.length===5"},{"d":"첫날은 0.05 다","js":"FRAMES[0].value[0]===0.05"},{"d":"확률이 계속 커진다","js":"FRAMES.every((f,i)=>i===0||f.value[0]>FRAMES[i-1].value[0])"},{"d":"확률이 1을 넘지 않는다","js":"FRAMES.every(f=>f.value[0]<=1)"}],"ex":"매일 들여다보며 <b>유의해지면 멈추는</b> 방식은 5% 수준을 지키지 못합니다 — 5일만 봐도 거짓 양성 확률이 23% 가까이 됩니다. '괜찮아 보일 때까지 기다렸다가 멈추는' 것은 사실상 <b>여러 번 검정하는 것</b>과 같기 때문입니다. 방어는 <b>표본 수를 미리 정하고 그때까지 보지 않는 것</b>, 또는 순차 검정(alpha spending·베이지안)처럼 <b>중간 확인을 전제로 설계된 방법</b>을 쓰는 것입니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}}]},{"t":"실행형 실전 — 통계량을 직접 계산한다","l":[{"t":"분산·사분위·상관·수렴","xp":80,"th":{"sum":"통계에서 틀리는 곳은 공식이 아니라 **분모와 기준선**이다. 표본인지 모집단인지, 무엇에 대한 비율인지가 값을 바꾼다.","body":[{"h":"분모가 값을 정한다","t":"표본 표준편차가 `n-1` 로 나누는 것은 표본 평균 기준으로 편차를 재면 **과소평가되기** 때문이다. 라이브러리 기본값도 다르다 — numpy 의 `std()` 는 모집단, 판다스의 `std()` 는 표본이라 같은 데이터에 다른 값이 나온다. 상관계수도 한쪽이 상수면 분모가 0이라 '관계 없음(0)' 이 아니라 **잴 수 없음** 이다."},{"h":"이상치와 수렴","t":"IQR 방식이 평균±표준편차보다 나은 이유는 이상치 자체에 끌려가지 않기 때문이다. 다만 '이상치' 가 '잘못된 값' 은 아니다 — 사기 탐지에서는 오히려 찾는 대상이다. 큰 수의 법칙은 수렴을 보장하지만 **속도는 1/√n** 이라, 정확도를 10배 높이려면 시행이 100배 필요하다."}],"code":{"c":"numpy  np.std(x)        # 분모 n   (모집단)\npandas pd.Series(x).std() # 분모 n-1 (표본)\n# 같은 데이터, 다른 값","cap":"어느 쪽인지 확인하지 않으면 재현되지 않는다"},"key":["표본 표준편차는 `n-1` — 라이브러리 기본값을 확인한다","IQR 이상치는 평균 기준보다 극단값에 강하다","상관은 선형 관계만 재고 인과가 아니다","분모가 0이면 '0' 이 아니라 '정의되지 않음'","표본이 적을 때 결론을 내지 않는다"]},"q":[{"t":"code","run":"js","k":"표본 표준편차의 분모","cat":"internals","q":"평균·<b>모집단 표준편차</b>(분모 n)·<b>표본 표준편차</b>(분모 n−1)를 구하세요. <code>stats(xs)</code> 는 <code>{mean, pstd, sstd}</code> 를 돌려주고, 값이 <b>1개면 sstd 는 null</b> 입니다.","src":"function stats(xs) {\n  // TODO: 분모가 다른 두 표준편차\n  return { mean: 0, pstd: 0, sstd: null };\n}","sol":"function stats(xs) {\n  const n = xs.length;\n  if (!n) return { mean: null, pstd: null, sstd: null };\n  const mean = xs.reduce((a, b) => a + b, 0) / n;\n  const ss = xs.reduce((a, b) => a + (b - mean) * (b - mean), 0);\n  return {\n    mean,\n    pstd: Math.sqrt(ss / n),\n    sstd: n > 1 ? Math.sqrt(ss / (n - 1)) : null,\n  };\n}","tests":[{"in":"stats([2,4,4,4,5,5,7,9]).mean","out":"5"},{"in":"stats([2,4,4,4,5,5,7,9]).pstd","out":"2"},{"in":"Math.round(stats([2,4,4,4,5,5,7,9]).sstd*1000)/1000","out":"2.138"},{"in":"stats([5]).sstd","out":"null"}],"edge":[{"in":"stats([]).mean","out":"null"},{"in":"stats([3,3,3]).pstd","out":"0"}],"ex":"🎯 분모가 <code>n</code> 이냐 <code>n-1</code> 이냐는 '<b>가진 데이터가 전부인가, 표본인가</b>' 로 갈립니다. 표본으로 모집단의 분산을 추정할 때 <code>n</code> 으로 나누면 <b>실제보다 작게</b> 나오므로 보정합니다(베셀 보정).\n💡 왜 작아지는가 — 편차를 <b>표본 평균</b> 기준으로 재는데, 표본 평균은 그 표본에 가장 가까운 값이라 편차가 과소평가됩니다. 자유도가 하나 줄었다고 표현합니다.\n⚠️ 라이브러리 기본값이 다릅니다. numpy 의 <code>std()</code> 는 기본이 <code>ddof=0</code>(모집단), 판다스의 <code>std()</code> 는 <code>ddof=1</code>(표본)입니다 — <b>같은 데이터에 다른 값</b>이 나오므로 어느 쪽인지 확인해야 합니다.\n🔧 데이터가 1개면 표본 표준편차는 <b>정의되지 않습니다</b>(0으로 나눔). 0으로 채우면 '변동이 없다' 는 거짓 정보가 됩니다."},{"t":"code","run":"js","k":"사분위와 이상치","cat":"internals","q":"사분위수와 <b>IQR 이상치</b>를 구하세요. <code>quartiles(xs)</code> 는 <code>{q1, q2, q3}</code> 를(정렬 후 <b>선형 보간</b>), <code>outliers(xs)</code> 는 <code>Q1−1.5×IQR</code> 미만이거나 <code>Q3+1.5×IQR</code> 초과인 값을 돌려줍니다.","src":"function pct(sorted, p) {\n  const i = (sorted.length - 1) * p;\n  const lo = Math.floor(i);\n  const hi = Math.ceil(i);\n  return sorted[lo] + (sorted[hi] - sorted[lo]) * (i - lo);\n}\n\nfunction quartiles(xs) {\n  // TODO\n  return { q1: 0, q2: 0, q3: 0 };\n}\n\nfunction outliers(xs) {\n  // TODO\n  return [];\n}","sol":"function pct(sorted, p) {\n  const i = (sorted.length - 1) * p;\n  const lo = Math.floor(i);\n  const hi = Math.ceil(i);\n  return sorted[lo] + (sorted[hi] - sorted[lo]) * (i - lo);\n}\n\nfunction quartiles(xs) {\n  const s = [...xs].sort((a, b) => a - b);\n  return { q1: pct(s, 0.25), q2: pct(s, 0.5), q3: pct(s, 0.75) };\n}\n\nfunction outliers(xs) {\n  const { q1, q3 } = quartiles(xs);\n  const iqr = q3 - q1;\n  return xs.filter((v) => v < q1 - 1.5 * iqr || v > q3 + 1.5 * iqr);\n}","tests":[{"in":"quartiles([1,2,3,4,5]).q2","out":"3"},{"in":"quartiles([1,2,3,4,5]).q1","out":"2"},{"in":"outliers([1,2,3,4,100])","out":"[100]"},{"in":"outliers([1,2,3,4,5])","out":"[]"}],"edge":[{"in":"(() => { const a=[3,1,2]; outliers(a); return a; })()","out":"[3,1,2]"},{"in":"quartiles([10]).q2","out":"10"}],"ex":"🎯 IQR 방식이 평균±표준편차보다 나은 이유는 <b>이상치에 강하다</b>는 것입니다. 평균과 표준편차는 이상치 자체에 끌려가므로, 극단값이 있으면 기준선이 함께 넓어져 그 값을 정상으로 판정합니다.\n💡 1.5 라는 계수는 정규분포에서 약 0.7% 가 걸리도록 정해진 관행값입니다 — 법칙이 아니라 <b>선택</b>이므로 도메인에 따라 3.0 을 쓰기도 합니다.\n⚠️ '이상치' 가 곧 '잘못된 값' 은 아닙니다. 진짜 극단 사건일 수도 있으므로 <b>지우기 전에 왜 그런지</b> 확인해야 합니다 — 사기 탐지에서는 이상치가 오히려 찾는 대상입니다.\n🔧 백분위 계산 방법이 여러 가지라 라이브러리마다 Q1 값이 다를 수 있습니다. 이 문항은 선형 보간(numpy 기본)을 씁니다. 그리고 <code>sort</code> 는 원본을 바꾸므로 복사 후 정렬해야 합니다 — 엣지 케이스가 그것을 검사합니다."},{"t":"code","run":"js","k":"상관계수","cat":"internals","q":"두 변수의 <b>피어슨 상관계수</b>를 구하세요. <code>corr(xs, ys)</code> 는 −1~1 사이 값을 돌려주고, 어느 한쪽의 <b>표준편차가 0이면</b> 정의되지 않으므로 <code>null</code> 입니다.","src":"function corr(xs, ys) {\n  // TODO: 공분산 / (표준편차 곱)\n  return 0;\n}","sol":"function corr(xs, ys) {\n  const n = xs.length;\n  if (n < 2 || ys.length !== n) return null;\n  const mx = xs.reduce((a, b) => a + b, 0) / n;\n  const my = ys.reduce((a, b) => a + b, 0) / n;\n  let cov = 0;\n  let vx = 0;\n  let vy = 0;\n  for (let i = 0; i < n; i++) {\n    const dx = xs[i] - mx;\n    const dy = ys[i] - my;\n    cov += dx * dy;\n    vx += dx * dx;\n    vy += dy * dy;\n  }\n  if (vx === 0 || vy === 0) return null;\n  return cov / Math.sqrt(vx * vy);\n}","tests":[{"in":"corr([1,2,3],[2,4,6])","out":"1"},{"in":"corr([1,2,3],[6,4,2])","out":"-1"},{"in":"Math.abs(corr([1,2,3,4],[1,3,2,4])-0.8)<1e-9","out":"true"},{"in":"corr([1,1,1],[1,2,3])","out":"null"}],"edge":[{"in":"corr([1],[1])","out":"null"},{"in":"Math.abs(corr([1,2,3,4,5],[2,4,6,8,10])-1)<1e-12","out":"true"}],"ex":"🎯 상관계수는 <b>선형 관계의 강도</b>만 잽니다. 완벽한 곡선 관계(y = x²)도 상관계수가 0에 가까울 수 있으므로, 값이 낮다고 '관계가 없다' 고 결론 내면 안 됩니다.\n⚠️ <b>상관은 인과가 아닙니다</b>. 아이스크림 판매와 익사 사고는 강한 상관이 있지만 원인은 '여름' 이라는 제3의 변수입니다.\n💡 한쪽이 <b>상수면 정의되지 않습니다</b> — 분모가 0이 됩니다. 0을 돌려주면 '관계 없음' 으로 읽히는데, 사실은 '잴 수 없음' 이라 완전히 다른 뜻입니다.\n🔧 상관계수는 이상치에 아주 민감합니다. 점 하나가 0.2 를 0.9 로 만들 수 있으므로 <b>산점도를 반드시 함께</b> 보세요 — 앤스컴의 4중주가 이걸 보여 주는 고전적인 예입니다."},{"t":"code","run":"js","k":"큰 수의 법칙","cat":"internals","q":"주사위를 n번 던진 평균이 기댓값 3.5 에 가까워지는지 확인하세요. 결정적으로 하기 위해 <b>1,2,3,4,5,6 을 순환</b>하며 던집니다. <code>runMean(n)</code> 은 n번 던진 평균을, <code>within(n, tol)</code> 은 3.5 와의 오차가 tol 이하인지 돌려줍니다.","src":"function roll(i) {\n  return (i % 6) + 1;\n}\n\nfunction runMean(n) {\n  // TODO\n  return 0;\n}\n\nfunction within(n, tol) {\n  return Math.abs(runMean(n) - 3.5) <= tol;\n}","sol":"function roll(i) {\n  return (i % 6) + 1;\n}\n\nfunction runMean(n) {\n  if (n <= 0) return null;\n  let s = 0;\n  for (let i = 0; i < n; i++) s += roll(i);\n  return s / n;\n}\n\nfunction within(n, tol) {\n  return Math.abs(runMean(n) - 3.5) <= tol;\n}","tests":[{"in":"runMean(6)","out":"3.5"},{"in":"runMean(1)","out":"1"},{"in":"within(60,0.01)","out":"true"},{"in":"within(1,0.01)","out":"false"}],"edge":[{"in":"runMean(0)","out":"null"},{"in":"within(600,0.005)","out":"true"}],"ex":"🎯 큰 수의 법칙은 '<b>시행이 늘면 표본 평균이 기댓값에 수렴한다</b>' 는 것입니다. 다만 수렴은 <b>보장</b>이지 <b>속도</b>가 아닙니다 — 오차는 대략 1/√n 로 줄어들므로 정확도를 10배 높이려면 시행을 100배 해야 합니다.\n⚠️ 흔한 오해가 '<b>도박사의 오류</b>' 입니다. 앞면이 연속 5번 나왔다고 뒷면이 나올 차례가 아닙니다 — 주사위는 과거를 기억하지 않고, 평균이 수렴하는 것은 <b>초기 편차가 희석되기</b> 때문이지 반대 결과가 보상해 주기 때문이 아닙니다.\n💡 그래서 <code>runMean(1) = 1</code> 처럼 작은 n 에서는 기댓값과 한참 멀 수 있습니다. A/B 테스트에서 표본이 적을 때 결론을 내면 안 되는 이유가 이것입니다.\n🔧 이 문항은 결정적으로 만들려고 순환 주사위를 썼습니다 — 실제 무작위였다면 같은 코드가 매번 다른 결과를 내 채점할 수 없습니다."}]}]},{"t":"실행형 실전 — 통계 알고리즘을 직접 만든다","l":[{"t":"추정과 가설 검정","xp":80,"th":{"sum":"모집단을 모를 때 **표본으로 불확실성을 측정하는** 방법들이다.","body":[{"h":"베셀 보정과 부트스트랩","t":"표본 분산을 구할 때 n 대신 n-1 로 나누는 베셀 보정은 표본 평균을 쓰면서 생기는 과소 추정을 상쇄한다. 부트스트랩은 복원 추출로 표본을 반복해서 뽑아 통계량의 분포를 시뮬레이션하며, 정규분포 가정이 필요 없고 어떤 복잡한 지표에도 적용할 수 있다."},{"h":"순열 검정과 이분산","t":"순열 검정은 두 그룹의 라벨을 무작위로 섞어 관측된 차이가 우연인지 확인하는 직관적인 방법이다. A/B 테스트에서 분산이 다를 때는 Student's t-test 대신 각자의 분산을 쓰고 자유도를 보수적으로 조정하는 Welch's t-test 를 써야 한다."}],"code":{"c":"sample = [data[random.randint(0, n - 1)] for _ in range(n)]","cap":"복원 추출이 부트스트랩의 핵심이다"},"key":["n-1 은 자유도 보정이다","부트스트랩은 복원 추출로 시뮬레이션한다","순열 검정은 차이가 우연인지 섞어본다","분산이 다를 때는 Welch's t-test 를 쓴다"]},"q":[{"t":"py","k":"편향 없는 표본 분산","cat":"internals","q":"<code>sample_variance(xs)</code> 를 구현하세요. 리스트 <code>xs</code> 의 표본 분산을 구합니다. 모집단 분산을 추정하기 위해 <code>n</code> 이 아니라 <b><code>n - 1</code> 로 나누어야</b> 합니다(베셀 보정). 결과는 <code>round(v, 4)</code> 로 감싸고, 요소가 2개 미만이면 <code>None</code> 입니다. 아래 구현은 n 으로 나눕니다.","src":"def sample_variance(xs):\n    n = len(xs)\n    if n < 2:\n        return None\n    mean = sum(xs) / n\n    # TODO: 모집단 분산을 추정하려면 n - 1 로 나누어야 한다\n    ss = sum((x - mean) ** 2 for x in xs)\n    return round(ss / n, 4)","sol":"def sample_variance(xs):\n    n = len(xs)\n    if n < 2:\n        return None\n    mean = sum(xs) / n\n    ss = sum((x - mean) ** 2 for x in xs)\n    return round(ss / (n - 1), 4)","tests":[{"in":"sample_variance([1, 2, 3, 4, 5])","out":"2.5"},{"in":"sample_variance([10, 10, 10])","out":"0.0"},{"in":"sample_variance([0, 100])","out":"5000.0"},{"in":"sample_variance([1])","out":"None"},{"in":"sample_variance([])","out":"None"}],"edge":[{"in":"sample_variance([-5, -3, -1, 1, 3, 5])","out":"14.0"},{"in":"sample_variance([0, 0, 0, 0, 1])","out":"0.2"}],"ex":"🎯 편향(Bias)의 핵심을 손으로 확인하는 문항입니다. 표본의 평균은 모평균과 다를 수밖에 없는데, 표본 분산을 계산할 때 모평균이 아닌 표본 평균을 사용하면 편차 제곱의 합이 수학적으로 항상 작게 나옵니다. 그래서 `n` 으로 나누면 분산을 과소 추정하게 됩니다.\n💡 베셀 보정(Bessel's correction)이라 불리는 `n-1` 나누기는 이 과소 추정을 정확히 상쇄해 기댓값을 모분산과 일치시킵니다. `n` 대신 `n-1` 을 쓰는 이유는 '표본 평균을 계산하는 데 데이터 정보(자유도) 하나를 썼기 때문' 이라고 이해하면 편합니다.\n⚠️ numpy 의 `np.var` 와 `np.std` 는 기본적으로 `n` 으로 나눕니다(`ddof=0`). 반면 pandas 의 `.var()` 와 `.std()` 는 기본적으로 `n-1` 로 나눕니다(`ddof=1`). 이 차이를 모르면 두 라이브러리를 섞어 쓸 때 이유 없이 값이 어긋납니다.\n🔧 기계학습에서 데이터 크기가 크면 `n` 이나 `n-1` 이나 차이가 거의 없지만, 실험 설계나 소표본 A/B 테스트에서는 분산의 미세한 차이가 p-value 에 직접적인 영향을 주므로 `ddof=1` 을 명시하는 습관이 안전합니다."},{"t":"py","k":"부트스트랩 신뢰구간","cat":"internals","q":"<code>bootstrap_ci(data, b, alpha, seed)</code> 를 구현하세요. 데이터에서 <b>복원 추출</b>로 크기가 같은 표본을 <code>b</code> 번 뽑아 각각의 평균을 구하고, 그 평균들의 하위 <code>alpha / 2</code> 와 상위 <code>1 - alpha / 2</code> 백분위수를 <code>[lower, upper]</code> 로 돌려줍니다. 인덱스는 <code>int(b * 백분위수)</code> 로 구하고 <code>round(x, 4)</code> 를 적용하세요. 아래 구현은 비복원 추출을 합니다.","src":"def bootstrap_ci(data, b, alpha, seed):\n    import random\n    random.seed(seed)\n    n = len(data)\n    means = []\n    for _ in range(b):\n        # TODO: 복원 추출(with replacement)이어야 한다\n        sample = random.sample(data, n)\n        means.append(sum(sample) / n)\n    means.sort()\n    lower = means[int(b * (alpha / 2))]\n    upper = means[int(b * (1 - alpha / 2))]\n    return [round(lower, 4), round(upper, 4)]","sol":"def bootstrap_ci(data, b, alpha, seed):\n    import random\n    random.seed(seed)\n    n = len(data)\n    means = []\n    for _ in range(b):\n        sample = [data[random.randint(0, n - 1)] for _ in range(n)]\n        means.append(sum(sample) / n)\n    means.sort()\n    lower = means[int(b * (alpha / 2))]\n    upper = means[int(b * (1 - alpha / 2))]\n    return [round(lower, 4), round(upper, 4)]","tests":[{"in":"bootstrap_ci([1, 2, 3, 4, 5], 1000, 0.05, 42)","out":"[1.8, 4.2]"},{"in":"bootstrap_ci([10, 20, 30], 500, 0.10, 42)","out":"[13.3333, 26.6667]"},{"in":"bootstrap_ci([0, 0, 0], 100, 0.05, 42)","out":"[0.0, 0.0]"},{"in":"bootstrap_ci([1, 100], 200, 0.05, 42)","out":"[1.0, 100.0]"}],"edge":[{"in":"bootstrap_ci([1, 2, 3], 10, 0.2, 42)","out":"[1.3333, 3.0]"}],"ex":"🎯 부트스트랩은 복잡한 수식 없이 **시뮬레이션으로 통계적 불확실성을 측정하는** 강력한 도구입니다. 핵심은 모집단을 모를 때 '현재 표본을 모집단으로 간주' 하고 반복해서 다시 뽑아(재표본) 통계량의 분포를 만드는 것입니다.\n⚠️ 비복원 추출(`random.sample`)로 표본 크기만큼 뽑으면 원래 데이터와 완벽히 같은 구성이 되므로, 평균은 매번 같아져 신뢰구간이 점(point)으로 수렴합니다. 부트스트랩이 성립하려면 반드시 **복원 추출**이어야 표본마다 구성을 조금씩 다르게 만들 수 있습니다.\n💡 정규분포 가정이 필요 없고 평균뿐 아니라 중앙값, 90분위수, 심지어 두 지표의 비율 등 수식으로 분산을 구하기 어려운 어떤 복잡한 지표라도 적용할 수 있다는 것이 실무적 가치입니다.\n🔧 단, 데이터가 너무 적거나(꼬리 분포를 반영 못 함) 시계열 데이터처럼 독립성이 깨진 경우에는 기본 부트스트랩이 틀린 결과를 냅니다. 이럴 때는 블록 단위로 뽑는 Block Bootstrap 을 써야 합니다."},{"t":"py","k":"순열 검정 (Permutation Test)","cat":"internals","q":"<code>permutation_test(x, y, b, seed)</code> 를 구현하세요. 두 그룹 <code>x, y</code> 간의 평균 차이가 우연인지 확인하기 위해, <b>두 데이터를 섞어 임의로 다시 두 그룹으로 나눈 뒤</b> 차이를 계산하는 과정을 <code>b</code> 번 반복합니다. 원래 관측된 차이 이상으로 큰 차이(절댓값)가 나올 비율(p-value)을 <code>round(p, 4)</code> 로 돌려줍니다. 입력이 비었으면 <code>None</code>. 아래 구현은 관측값과 임의값을 잘못 비교합니다.","src":"def permutation_test(x, y, b, seed):\n    import random\n    random.seed(seed)\n    if not x or not y:\n        return None\n    def mean(arr): return sum(arr) / len(arr)\n    obs = abs(mean(x) - mean(y))\n    pool = x + y\n    nx = len(x)\n    count = 0\n    for _ in range(b):\n        shuffled = pool[:]\n        random.shuffle(shuffled)\n        diff = abs(mean(shuffled[:nx]) - mean(shuffled[nx:]))\n        # TODO: 관측값 '이상' 이 나오는 비율을 세어야 한다\n        if diff < obs:\n            count += 1\n    return round(count / b, 4)","sol":"def permutation_test(x, y, b, seed):\n    import random\n    random.seed(seed)\n    if not x or not y:\n        return None\n    def mean(arr): return sum(arr) / len(arr)\n    obs = abs(mean(x) - mean(y))\n    pool = x + y\n    nx = len(x)\n    count = 0\n    for _ in range(b):\n        shuffled = pool[:]\n        random.shuffle(shuffled)\n        diff = abs(mean(shuffled[:nx]) - mean(shuffled[nx:]))\n        if diff >= obs:\n            count += 1\n    return round(count / b, 4)","tests":[{"in":"permutation_test([1, 2, 3], [4, 5, 6], 1000, 42)","out":"0.121"},{"in":"permutation_test([1, 1], [1, 1], 100, 42)","out":"1.0"},{"in":"permutation_test([10, 20], [15, 25], 500, 42)","out":"0.722"},{"in":"permutation_test([0], [100], 100, 42)","out":"1.0"}],"edge":[{"in":"permutation_test([], [1, 2], 10, 42)","out":"None"}],"ex":"🎯 A/B 테스트에서 가장 직관적인 검정 방법입니다. 'A 와 B 에 차이가 없다(귀무가설)' 면 라벨을 무작위로 섞어도 원래 관측된 차이만큼 큰 차이가 종종 나와야 합니다. 섞었는데도 원래 차이보다 큰 경우가 거의 없다면(p-value 가 작다면), 우연이 아니라고 결론 내릴 수 있습니다.\n⚠️ 버그 코드처럼 `diff < obs` (작은 경우)를 세면 p-value 의 정의가 정반대가 됩니다. p-value 는 관측된 결과 '이상' 으로 극단적인 결과가 우연히 나올 확률입니다.\n💡 t-test 와 목적은 같지만, 정규분포 가정이 필요 없고 이상치에 덜 민감하며 작은 표본에서도 정확하다는 장점이 있습니다.\n🔧 단점은 계산 비용입니다. 데이터가 많아지면 섞고 계산하는 과정이 수만 번 반복되어야 해서 느립니다. 실무에서는 표본이 크면 근사가 잘 되는 t-test 나 부트스트랩을 쓰고, 샘플이 아주 적을 때 순열 검정으로 확신을 얻는 용도로 씁니다."}]},{"t":"오류와 역설","xp":80,"th":{"sum":"통계적 직관이 **실제 계산에서 어떻게 깨지는지** 확인한다.","body":[{"h":"다중 비교와 심프슨의 역설","t":"여러 가설을 동시에 검정하면 효과가 없어도 우연히 유의미하다고 나오는 다중 비교 문제가 생긴다. BH 보정은 FDR 을 통제하면서도 검정력을 유지한다. 심프슨의 역설은 부분에서 성립하던 관계가 전체로 합쳤을 때 교란 변수 때문에 뒤집히는 현상으로, 데이터를 항상 세그먼트로 쪼개서 확인해야 하는 이유다."},{"h":"베이즈 갱신과 표본 크기","t":"거짓 양성 역설은 검사기 정확도가 높아도 희귀병의 경우 실제 걸렸을 확률이 낮은 현상으로, 사전 확률의 강력한 닻 역할을 보여준다. 목표 오차를 절반으로 줄이려면 표본은 2배가 아니라 4배가 필요하며, 사람 수는 언제나 올림(ceil)해야 한다."}],"code":{"c":"if sorted_p[i][1] <= (k / m) * alpha:\n    k_max = k","cap":"BH 보정은 p-value 순위에 비례해 기준을 완화한다"},"key":["다중 비교는 BH 로 보정한다","심프슨의 역설은 교란 변수가 원인이다","베이즈 갱신은 사전 확률이 중요하다","오차를 절반으로 줄이려면 표본은 4배다"]},"q":[{"t":"py","k":"Welch's t-test 자유도","cat":"internals","q":"<code>welch_df(v1, n1, v2, n2)</code> 를 구현하세요. 분산이 다를 때(이분산) t-검정을 수행하는 Welch's t-test 의 <b>근사 자유도(df)</b>를 계산합니다. <code>(v1/n1 + v2/n2)^2 / ((v1/n1)^2/(n1-1) + (v2/n2)^2/(n2-1))</code> 입니다. <code>n1, n2</code> 가 1 이하거나 분모가 0이면 <code>0.0</code> 이며 결과는 <code>round(df, 4)</code> 입니다. 아래 코드는 분자 계산에 괄호가 빠졌습니다.","src":"def welch_df(v1, n1, v2, n2):\n    if n1 <= 1 or n2 <= 1:\n        return 0.0\n    # TODO: 분자 전체의 제곱이어야 한다\n    num = v1 / n1 + v2 / n2 ** 2\n    den = (v1 / n1) ** 2 / (n1 - 1) + (v2 / n2) ** 2 / (n2 - 1)\n    if den == 0:\n        return 0.0\n    return round(num / den, 4)","sol":"def welch_df(v1, n1, v2, n2):\n    if n1 <= 1 or n2 <= 1:\n        return 0.0\n    num = (v1 / n1 + v2 / n2) ** 2\n    den = (v1 / n1) ** 2 / (n1 - 1) + (v2 / n2) ** 2 / (n2 - 1)\n    if den == 0:\n        return 0.0\n    return round(num / den, 4)","tests":[{"in":"welch_df(2.0, 10, 3.0, 15)","out":"21.913"},{"in":"welch_df(1.0, 10, 1.0, 10)","out":"18.0"},{"in":"welch_df(100.0, 50, 1.0, 50)","out":"49.9799"},{"in":"welch_df(0.0, 10, 0.0, 10)","out":"0.0"}],"edge":[{"in":"welch_df(5.0, 1, 3.0, 10)","out":"0.0"}],"ex":"🎯 A/B 테스트에서 두 그룹의 분산이 같다는 가정은 대부분 틀립니다(효과가 있는 그룹은 대개 분산도 커집니다). Student's t-test 는 분산이 같다고 가정해 pooled variance 를 쓰지만, Welch's t-test 는 각자의 분산을 쓰고 자유도를 조정해 이 문제를 해결합니다.\n💡 두 번째 테스트를 보면 분산과 표본 크기가 같을 때 자유도가 `n1 + n2 - 2` (10 + 10 - 2 = 18)로 Student 와 똑같아집니다. 하지만 세 번째 테스트처럼 분산 차이가 극심하면 자유도가 49 로 뚝 떨어져 보수적인 검정을 하게 됩니다.\n⚠️ 분자와 분모 계산에 제곱 연산과 나눗셈이 섞여 있어 괄호를 하나만 실수해도 값이 완전히 달라지고, 그 결과로 p-value 가 엉뚱해집니다. 이 공식(Satterthwaite approximation)은 꽤 길지만 통계 라이브러리 깊은 곳에서 항상 돌아가고 있습니다.\n🔧 R 과 Scipy 의 `ttest_ind` 는 기본값이 다릅니다. R 은 기본적으로 이분산을 가정해 Welch 를 쓰지만, 파이썬 Scipy 는 기본값이 Student(`equal_var=True`)입니다. 현대 통계학에서는 항상 Welch's t-test 를 쓰는 것을 권장하므로 파이썬에서는 `equal_var=False` 를 습관적으로 켜야 합니다."},{"t":"py","k":"다중 비교 BH 보정","cat":"internals","q":"<code>bh_correction(p_values, alpha)</code> 를 구현하세요. 여러 가설을 동시에 검정할 때 <b>거짓 발견율(FDR)</b>을 <code>alpha</code> 이하로 통제하는 Benjamini-Hochberg 절차입니다. p-value 를 오름차순 정렬하고, <code>p_i <= (i / m) * alpha</code> (i 는 1부터 시작)를 만족하는 <b>가장 큰 i</b> 를 찾아, 그보다 작거나 같은 순위의 가설 인덱스를 정렬해 돌려줍니다. 만족하는 가설이 없으면 <code>[]</code>. 아래 구현은 모든 인덱스를 돌려줍니다.","src":"def bh_correction(p_values, alpha):\n    m = len(p_values)\n    if m == 0:\n        return []\n    sorted_p = sorted(enumerate(p_values), key=lambda x: x[1])\n    k_max = 0\n    for i in range(m):\n        k = i + 1\n        if sorted_p[i][1] <= (k / m) * alpha:\n            k_max = k\n    if k_max == 0:\n        return []\n    # TODO: 인덱스 k_max 개만 돌려줘야 한다\n    rejected = [idx for idx, _ in sorted_p]\n    return sorted(rejected)","sol":"def bh_correction(p_values, alpha):\n    m = len(p_values)\n    if m == 0:\n        return []\n    sorted_p = sorted(enumerate(p_values), key=lambda x: x[1])\n    k_max = 0\n    for i in range(m):\n        k = i + 1\n        if sorted_p[i][1] <= (k / m) * alpha:\n            k_max = k\n    if k_max == 0:\n        return []\n    rejected = [idx for idx, _ in sorted_p[:k_max]]\n    return sorted(rejected)","tests":[{"in":"bh_correction([0.01, 0.05, 0.03, 0.04, 0.2], 0.1)","out":"[0, 1, 2, 3]"},{"in":"bh_correction([0.06, 0.1, 0.2], 0.05)","out":"[]"},{"in":"bh_correction([0.001, 0.002, 0.003], 0.05)","out":"[0, 1, 2]"},{"in":"bh_correction([0.04, 0.041, 0.042], 0.05)","out":"[0, 1, 2]"}],"edge":[{"in":"bh_correction([], 0.05)","out":"[]"}],"ex":"🎯 100번의 독립적인 A/B 테스트를 하면, 효과가 전혀 없어도 유의수준 5% 에 의해 우연히 5개는 '효과가 있다(p < 0.05)' 고 나옵니다. 이것이 다중 비교 문제(Multiple Comparisons Problem)입니다.\n💡 Bonferroni 보정은 기준을 무조건 `alpha / m` 으로 나누어 너무 빡빡합니다. 반면 BH 절차는 p-value 의 순위에 비례해 기준을 완화(`(i / m) * alpha`)하여, '발견된 것 중 가짜의 비율(FDR)' 을 통제하면서도 통계적 검정력을 유지합니다.\n⚠️ 주의할 점은 '가장 큰 i' 를 찾는다는 것입니다. 중간에 부등식을 만족하지 않는 p-value 가 있어도, 그 뒤에 더 큰 i 에서 부등식을 만족하면 앞의 가설들도 전부 기각합니다.\n🔧 추천 시스템 A/B 테스트나 유전자 발현 분석처럼 동시에 수백 수천 개의 가설을 검정할 때는 단순히 p < 0.05 를 보면 완전히 잘못된 결론을 냅니다. 현대 데이터 분석에서 p-value 를 볼 때 반드시 세트로 따라와야 하는 보정 절차입니다."},{"t":"py","k":"심프슨의 역설","cat":"design","q":"<code>simpsons_paradox(records)</code> 를 구현하세요. 각 레코드는 <code>{'g': 'A'|'B', 'd': 부서, 's': 성공여부(bool)}</code> 입니다. <b>전체 성공률</b>은 A 가 B 보다 크지만(<code>A > B</code>), <b>모든 개별 부서</b> 내에서는 B 의 성공률이 A <b>이상</b>인 경우(<code>B >= A</code>) <code>True</code> 를 돌려줍니다. 어느 한쪽 그룹이 빈 부서가 있거나 그룹 자체가 비었으면 <code>False</code>. 아래 구현은 전체 성공률만 비교합니다.","src":"def simpsons_paradox(records):\n    def rate(recs):\n        if not recs: return 0.0\n        return sum(1 for r in recs if r['s']) / len(recs)\n    a_recs = [r for r in records if r['g'] == 'A']\n    b_recs = [r for r in records if r['g'] == 'B']\n    if not a_recs or not b_recs:\n        return False\n    # TODO: 개별 부서 조건이 누락되었다\n    return rate(a_recs) > rate(b_recs)","sol":"def simpsons_paradox(records):\n    def rate(recs):\n        if not recs: return 0.0\n        return sum(1 for r in recs if r['s']) / len(recs)\n    a_recs = [r for r in records if r['g'] == 'A']\n    b_recs = [r for r in records if r['g'] == 'B']\n    if not a_recs or not b_recs:\n        return False\n    oa = rate(a_recs)\n    ob = rate(b_recs)\n    depts = set(r['d'] for r in records)\n    for d in depts:\n        ad = [r for r in a_recs if r['d'] == d]\n        bd = [r for r in b_recs if r['d'] == d]\n        if not ad or not bd:\n            return False\n        if rate(bd) < rate(ad):  # B 가 A 이상이어야 하므로 작으면 False\n            return False\n    return oa > ob","tests":[{"in":"simpsons_paradox([{'g':'A','d':1,'s':1},{'g':'A','d':1,'s':1},{'g':'A','d':1,'s':1},{'g':'A','d':1,'s':0},{'g':'A','d':2,'s':0},{'g':'B','d':1,'s':1},{'g':'B','d':2,'s':1},{'g':'B','d':2,'s':0},{'g':'B','d':2,'s':0},{'g':'B','d':2,'s':0}])","out":"True"},{"in":"simpsons_paradox([{'g':'A','d':1,'s':1},{'g':'B','d':1,'s':0}])","out":"False"},{"in":"simpsons_paradox([{'g':'A','d':1,'s':1},{'g':'B','d':2,'s':1}])","out":"False"},{"in":"simpsons_paradox([])","out":"False"}],"edge":[{"in":"simpsons_paradox([{'g':'A','d':1,'s':0},{'g':'B','d':1,'s':1}])","out":"False"}],"ex":"🎯 심프슨의 역설은 부분에서 성립하던 관계가 데이터를 모두 합쳤을 때 뒤집히는 현상입니다. 이 역설이 왜 무서운지 눈으로 확인하게 하는 코딩입니다. 첫 번째 테스트를 보면, 전체 성공률은 A가 60%(3/5), B가 40%(2/5) 로 A가 높게 나오지만, 부서별로 보면 1부서(A:75%, B:100%), 2부서(A:0%, B:25%) 로 무조건 B 가 더 잘합니다.\n💡 원인은 교란 변수(Confounding variable)에 있습니다. A 는 '성공률이 원래 높은 1부서' 에 표본이 몰려 있고, B 는 '원래 낮은 2부서' 에 몰려 있으면 합쳤을 때 A 가 유리해 보입니다.\n⚠️ 실무에서 대시보드만 보고 결정을 내리면 안 되는 이유입니다. '전체 모바일 유저의 전환율이 올랐다' 고 좋아했는데, 알고 보니 안드로이드와 iOS 각각에서는 모두 떨어졌지만 전환율이 높은 iOS 유저 비중이 늘어나서 전체 지표가 오르는 일이 흔합니다.\n🔧 데이터를 분석할 때 항상 주요 세그먼트(성별, 기기, 국가, 시간대)로 '쪼개서' 트렌드가 일관된지 확인해야 합니다. 혼합 효과 모델(Mixed Effects Model)도 이 문제를 해결하는 통계적 기법 중 하나입니다."}]},{"t":"기계학습의 통계 기반","xp":80,"th":{"sum":"실무 시스템과 기계학습 내부에서 돌아가는 **통계적 계산**들이다.","body":[{"h":"스트림과 시계열 평활화","t":"EWMA(지수 가중 이동 평균)는 최근 데이터에 가중치를 두면서도 과거를 잊지 않아 스트리밍이나 옵티마이저에 쓰인다. 저수지 샘플링(Reservoir Sampling)은 전체 크기를 모르는 무한한 데이터 스트림에서 메모리를 O(k) 만 쓰고 고르게 k 개를 추출하는 알고리즘이다."},{"h":"불균형과 불순도","t":"불균형 데이터에서는 정밀도와 재현율의 조화평균인 F1 Score 가 유효하며, 0 나누기 방어가 필수다. 지니 불순도는 엔트로피보다 계산이 빠르면서도 트리가 얼마나 순수해지는지 효과적으로 측정하여 의사결정나무의 기본 분할 기준으로 쓰인다."}],"code":{"c":"j = random.randint(0, i) # 0 부터 i 까지\nif j < k: res[j] = item","cap":"저수지 샘플링의 교체 확률은 k/(i+1) 이다"},"key":["EWMA 는 매끄러운 갱신을 한다","저수지 샘플링은 무한 스트림에서 고르게 뽑는다","F1 Score 는 0 나누기를 방어해야 한다","지니 불순도는 제곱합으로 계산한다"]},"q":[{"t":"py","k":"베이즈 갱신","cat":"internals","q":"<code>bayes_update(prior_h1, likelihoods, evidence_seq)</code> 를 구현하세요. H1 과 H2 두 가설이 있고, 초기 확률은 <code>prior_h1</code> 과 <code>1 - prior_h1</code> 입니다. <code>likelihoods</code> 는 증거 <code>e</code> 에 대해 <code>(P(e|H1), P(e|H2))</code> 를 매핑합니다. <code>evidence_seq</code> 증거가 차례로 들어올 때마다 사후 확률을 갱신해 최종 H1 의 확률을 <code>round(p, 4)</code> 로 돌려줍니다. 확률 분모가 0이 되면 <code>0.0</code>. 모르는 증거는 무시합니다. 아래 구현은 베이즈 정리가 아닌 단순히 우도를 더합니다.","src":"def bayes_update(prior_h1, likelihoods, evidence_seq):\n    p_h1 = prior_h1\n    p_h2 = 1.0 - prior_h1\n    for e in evidence_seq:\n        if e not in likelihoods:\n            continue\n        l1, l2 = likelihoods[e]\n        # TODO: 베이즈 정리는 P(H1|e) = P(e|H1)*P(H1) / P(e) 이다\n        p_h1 += l1\n        p_h2 += l2\n    total = p_h1 + p_h2\n    return round(p_h1 / total, 4) if total else 0.0","sol":"def bayes_update(prior_h1, likelihoods, evidence_seq):\n    p_h1 = prior_h1\n    p_h2 = 1.0 - prior_h1\n    for e in evidence_seq:\n        if e not in likelihoods:\n            continue\n        l1, l2 = likelihoods[e]\n        p_e = l1 * p_h1 + l2 * p_h2\n        if p_e == 0:\n            return 0.0\n        p_h1 = (l1 * p_h1) / p_e\n        p_h2 = (l2 * p_h2) / p_e\n    return round(p_h1, 4)","tests":[{"in":"bayes_update(0.5, {'pos': (0.9, 0.1), 'neg': (0.1, 0.9)}, ['pos'])","out":"0.9"},{"in":"bayes_update(0.5, {'pos': (0.9, 0.1), 'neg': (0.1, 0.9)}, ['pos', 'pos'])","out":"0.9878"},{"in":"bayes_update(0.01, {'pos': (0.9, 0.1)}, ['pos'])","out":"0.0833"},{"in":"bayes_update(0.5, {'A': (1.0, 0.0)}, ['A'])","out":"1.0"},{"in":"bayes_update(0.5, {}, ['unknown'])","out":"0.5"}],"edge":[{"in":"bayes_update(0.5, {'pos': (0.0, 0.0)}, ['pos'])","out":"0.0"}],"ex":"🎯 베이즈 정리의 본질은 '새로운 증거가 들어왔을 때 내 믿음을 어떻게 갱신할 것인가' 입니다. $P(H|e) = \\frac{P(e|H)P(H)}{P(e)}$ 공식에서 이전 단계의 사후 확률 $P(H|e)$ 이 다음 단계의 사전 확률 $P(H)$ 로 자연스럽게 이어지는 것을 코드로 구현했습니다.\n💡 세 번째 테스트(0.01 사전 확률)가 이른바 '거짓 양성 역설(Base rate fallacy)' 입니다. 정확도가 90% 인 검사기라도 희귀병(1%)에 양성이 떴을 때 진짜 병에 걸렸을 확률은 90% 가 아니라 8.3% 에 불과합니다. 사전 확률이 얼마나 강력한 닻 역할을 하는지 보여 줍니다.\n⚠️ 우도를 단순히 더하거나 곱하기만 하면 분모로 정규화하는 과정($P(e)$ 로 나누기)이 빠져 확률의 합이 1을 넘거나 0에 수렴해 버립니다. 매 단계 갱신을 정확히 해야 합니다.\n🔧 스팸 필터(나이브 베이즈 분류기)가 정확히 이 과정을 수만 단어에 대해 수행합니다. 단어 하나하나가 증거(evidence)가 되어 스팸 가설의 확률을 계속 올리거나 내리는 방식입니다."},{"t":"py","k":"목표 표본 크기 산정","cat":"internals","q":"<code>sample_size_prop(z, p, e)</code> 를 구현하세요. 비율 추정에서 오차 한계(Margin of Error)를 <code>e</code> 이하로 맞추기 위한 <b>최소 표본 크기 <code>n</code></b> 을 구합니다. 공식은 <code>n = (z^2 * p * (1 - p)) / e^2</code> 이고, 사람은 나눌 수 없으므로 항상 <b>올림(ceil)</b>해야 합니다. <code>e <= 0</code> 이면 <code>None</code>. 아래 구현은 올림 대신 반올림을 합니다.","src":"def sample_size_prop(z, p, e):\n    if e <= 0: return None\n    n = (z ** 2 * p * (1 - p)) / (e ** 2)\n    # TODO: 보수적으로 무조건 올림해야 한다\n    return round(n)","sol":"def sample_size_prop(z, p, e):\n    import math\n    if e <= 0: return None\n    n = (z ** 2 * p * (1 - p)) / (e ** 2)\n    return math.ceil(n)","tests":[{"in":"sample_size_prop(1.96, 0.5, 0.05)","out":"385"},{"in":"sample_size_prop(2.58, 0.5, 0.01)","out":"16641"},{"in":"sample_size_prop(1.96, 0.1, 0.05)","out":"139"},{"in":"sample_size_prop(1.96, 0.5, 0)","out":"None"}],"edge":[{"in":"sample_size_prop(1.96, 0.5, 0.5)","out":"4"}],"ex":"🎯 A/B 테스트를 시작하기 전에 반드시 묻게 되는 질문, '며칠이나 돌려야 하나요?' 에 대답하는 공식입니다. 표본 크기는 목표하는 신뢰도(z)와 오차(e), 그리고 기저 비율(p)에 의해 결정됩니다.\n⚠️ `round` 나 `int` 로 내림을 해버리면 요구하는 오차 한계(e)를 아주 미세하게 만족시키지 못하는 경우가 생깁니다. 표본 크기는 항상 보수적으로 넉넉히 잡아야 하므로 무조건 `ceil` 로 올려야 합니다.\n💡 `p=0.5` 일 때 `p(1-p)` 가 0.25 로 최대가 됩니다. 첫 번째 테스트를 보면 오차 5% 를 맞추려면 약 385명(또는 개)의 응답이 필요합니다. 만약 비율을 모른다면 가장 보수적인 0.5 를 넣고 계산하는 것이 표준 절차입니다.\n🔧 오차(e)를 절반(0.05 -> 0.025)으로 줄이려면 표본은 2배가 아니라 **4배**가 필요합니다(분모에 제곱). 데이터를 두 배 더 모았다고 확신이 두 배가 되지는 않는다는, 통계학의 비정한 법칙입니다."},{"t":"py","k":"지수 가중 이동 평균 (EWMA)","cat":"internals","q":"<code>ewma(xs, alpha)</code> 를 구현하세요. 시계열 데이터 <code>xs</code> 에 대해 <b>현재 값에 <code>alpha</code>, 과거 평균에 <code>(1 - alpha)</code></b> 가중치를 두어 계산합니다. 첫 번째 값은 <code>xs[0]</code> 을 그대로 씁니다. 결과를 <code>round(v, 4)</code> 로 매핑해 돌려주고 빈 입력은 <code>[]</code>. 아래 구현은 최신 값을 무시합니다.","src":"def ewma(xs, alpha):\n    if not xs:\n        return []\n    out = [xs[0]]\n    for x in xs[1:]:\n        # TODO: 과거 평균만 남기고 최신 값(x)을 누락했다\n        out.append((1 - alpha) * out[-1])\n    return [round(v, 4) for v in out]","sol":"def ewma(xs, alpha):\n    if not xs:\n        return []\n    out = [xs[0]]\n    for x in xs[1:]:\n        out.append(alpha * x + (1 - alpha) * out[-1])\n    return [round(v, 4) for v in out]","tests":[{"in":"ewma([10, 20, 30], 0.5)","out":"[10, 15.0, 22.5]"},{"in":"ewma([10, 10, 10], 0.1)","out":"[10, 10.0, 10.0]"},{"in":"ewma([0, 100], 1.0)","out":"[0, 100.0]"},{"in":"ewma([100, 0], 0.0)","out":"[100, 100.0]"}],"edge":[{"in":"ewma([], 0.5)","out":"[]"}],"ex":"🎯 지수 가중 이동 평균(EWMA)은 최근 데이터에 더 큰 가중치를 두면서도 과거의 모든 데이터를 버리지 않고 지수적으로 감소시키며 반영하는 우아한 방법입니다. 상태를 저장할 변수가 직전 평균값 하나뿐이라 스트리밍 데이터에 제격입니다.\n💡 극단적인 가중치를 보면 이해가 쉽습니다. 세 번째 테스트처럼 `alpha=1.0` 이면 과거를 완전히 잊고 최신 값만 따라갑니다(순수 관측). 반대로 `alpha=0.0` 이면 첫 값만 고집합니다. 이 둘을 얼마나 섞을지가 `alpha` 의 역할입니다.\n⚠️ 딥러닝 옵티마이저(Adam, RMSprop)의 모멘텀이나 배치 정규화(Batch Normalization)의 이동 평균 추정 등 기계학습 내부에서 정말 많이 쓰이는 공식입니다.\n🔧 단순히 산술 이동 평균(Rolling Mean)을 쓰면 과거 데이터가 윈도우를 벗어나는 순간 값이 툭 떨어지는 '절벽 효과' 가 생기지만, EWMA 는 매끄럽게 감소하므로 노이즈가 많은 금융 시계열 평활화에 선호됩니다."},{"t":"py","k":"F1 Score 와 0 나누기","cat":"debug","q":"<code>f1_score(y_true, y_pred)</code> 를 구현하세요. 이진 분류의 정밀도(Precision)와 재현율(Recall)의 조화평균입니다. TP, FP, FN 을 직접 세고, 분모가 0이 되어 지표를 정의할 수 없으면 0.0 처리 후 <code>round(v, 4)</code> 를 돌려줍니다. 아래 구현은 아무것도 맞추지 못했을 때 예외가 터집니다.","src":"def f1_score(y_true, y_pred):\n    tp = fp = fn = 0\n    for t, p in zip(y_true, y_pred):\n        if t == 1 and p == 1: tp += 1\n        elif t == 0 and p == 1: fp += 1\n        elif t == 1 and p == 0: fn += 1\n    # TODO: 양성 예측이 전혀 없거나(Precision 0/0), 진짜 양성이 전혀 없으면(Recall 0/0)\n    precision = tp / (tp + fp)\n    recall = tp / (tp + fn)\n    return round(2 * precision * recall / (precision + recall), 4)","sol":"def f1_score(y_true, y_pred):\n    tp = fp = fn = 0\n    for t, p in zip(y_true, y_pred):\n        if t == 1 and p == 1:\n            tp += 1\n        elif t == 0 and p == 1:\n            fp += 1\n        elif t == 1 and p == 0:\n            fn += 1\n    precision = tp / (tp + fp) if (tp + fp) > 0 else 0\n    recall = tp / (tp + fn) if (tp + fn) > 0 else 0\n    if precision + recall == 0:\n        return 0.0\n    return round(2 * precision * recall / (precision + recall), 4)","tests":[{"in":"f1_score([1, 0, 1, 1], [1, 0, 0, 1])","out":"0.8"},{"in":"f1_score([0, 0, 0], [1, 1, 1])","out":"0.0"},{"in":"f1_score([1, 1], [0, 0])","out":"0.0"},{"in":"f1_score([0, 0], [0, 0])","out":"0.0"}],"edge":[{"in":"f1_score([1], [1])","out":"1.0"}],"ex":"🎯 데이터 불균형이 심할 때(예: 희귀병 진단, 불량품 탐지) 정확도(Accuracy)는 99% 라도 모델은 무가치할 수 있습니다. 그래서 양성(Positive) 예측에 초점을 맞춘 Precision 과 Recall 의 조화평균인 F1 Score 를 씁니다.\n⚠️ 이 구현의 가장 흔한 실수는 0 나누기(ZeroDivisionError) 방어를 잊는 것입니다. 두 번째 테스트처럼 모델이 양성을 한 번도 예측하지 않거나(tp+fp=0), 실제 양성이 아예 없거나(tp+fn=0), 둘 다 0이 되어 버리면 파이썬은 자비 없이 스크립트를 터뜨립니다. 파이프라인에서 수백 개의 배치를 돌리다 하나라도 0 이 나오면 학습이 통째로 멈춥니다.\n💡 산술평균이 아닌 조화평균을 쓰는 이유는, 한쪽이라도 낮으면 전체 점수를 가혹하게 깎아내리기 위해서입니다. Precision 1.0, Recall 0.1 이면 평균은 0.55 가 아니라 0.18 입니다. 모델이 꼼수를 쓰지 못하게 하는 페널티입니다.\n🔧 scikit-learn 의 `f1_score` 역시 이 0/0 상황에서 경고를 내고 0 을 반환(`zero_division=0` 기본값)합니다."},{"t":"py","k":"지니 불순도 (Gini Impurity)","cat":"internals","q":"<code>gini_impurity(labels)</code> 를 구현하세요. 의사결정나무에서 노드의 불순도를 재는 지표로, 수식은 <code>1 - sum(p_i^2)</code> (p_i 는 각 클래스의 비율) 입니다. 결과는 <code>round(v, 4)</code> 이고, 입력이 비었으면 <code>0.0</code> 입니다. 아래 구현은 엔트로피와 헷갈렸습니다.","src":"def gini_impurity(labels):\n    if not labels:\n        return 0.0\n    counts = {}\n    for l in labels:\n        counts[l] = counts.get(l, 0) + 1\n    n = len(labels)\n    # TODO: 지니 불순도는 1 - 확률의 제곱합이다\n    import math\n    imp = -sum((c / n) * math.log2(c / n) for c in counts.values())\n    return round(imp, 4)","sol":"def gini_impurity(labels):\n    if not labels:\n        return 0.0\n    counts = {}\n    for l in labels:\n        counts[l] = counts.get(l, 0) + 1\n    n = len(labels)\n    imp = 1.0 - sum((c / n) ** 2 for c in counts.values())\n    return round(imp, 4)","tests":[{"in":"gini_impurity(['A', 'A', 'A'])","out":"0.0"},{"in":"gini_impurity(['A', 'B'])","out":"0.5"},{"in":"gini_impurity(['A', 'B', 'B', 'C'])","out":"0.625"},{"in":"gini_impurity([])","out":"0.0"}],"edge":[{"in":"gini_impurity(['X'])","out":"0.0"}],"ex":"🎯 지니 불순도는 트리 모델(Random Forest, XGBoost)이 가지를 칠 때 '얼마나 섞여 있는가' 를 판단하는 기준입니다. 한 클래스만 있으면 0 (완벽히 순수)이 되고, 여러 클래스가 골고루 섞일수록 값이 커집니다(최대 0.5 또는 1 - 1/k).\n💡 정보 이득을 구하는 엔트로피(Entropy)와 자주 비교됩니다. 버그 코드가 짠 것이 엔트로피인데, 로그($\\log_2$) 계산이 들어가서 상대적으로 연산이 무겁습니다. 반면 지니는 제곱 연산만 쓰기 때문에 빠르고, 결과 양상은 거의 비슷해 실무 트리 모델들의 기본 분할 기준으로 널리 쓰입니다.\n⚠️ 불순도 계산 자체는 간단하지만, 트리를 만들 때는 모든 특성과 분할 점에 대해 이 계산을 수만 번 반복해야 하므로 성능 최적화가 필수적입니다.\n🔧 특성 중요도(Feature Importance) 역시 이 지니 불순도의 감소량을 노드마다 누적해서 구하는 것입니다. 트리가 '이 특성 덕분에 얼마나 순수해졌는가' 가 곧 그 특성의 기여도가 됩니다."},{"t":"py","k":"저수지 샘플링 (Reservoir Sampling)","cat":"design","q":"<code>reservoir_sample(stream, k, seed)</code> 를 구현하세요. 길이를 미리 알 수 없는 데이터 스트림에서 <code>k</code> 개를 <b>균등한 확률</b>로 복원 없이 추출하는 온라인 알고리즘입니다. 처음 k 개는 채우고, <code>i</code> 번째 원소(i=0 부터)는 <code>0 ~ i</code> 사이의 난수 <code>j</code> 를 뽑아 <code>j < k</code> 이면 저수지의 <code>j</code> 번째를 교체합니다. 아래 구현은 교체 확률이 틀렸습니다.","src":"def reservoir_sample(stream, k, seed):\n    import random\n    random.seed(seed)\n    res = []\n    for i, item in enumerate(stream):\n        if i < k:\n            res.append(item)\n        else:\n            # TODO: i 번째 아이템이 선택될 확률이 k/(i+1) 이어야 한다\n            j = random.randint(0, k)\n            if j < k:\n                res[j] = item\n    return res","sol":"def reservoir_sample(stream, k, seed):\n    import random\n    random.seed(seed)\n    res = []\n    for i, item in enumerate(stream):\n        if i < k:\n            res.append(item)\n        else:\n            j = random.randint(0, i)   # 0 부터 i 까지 (확률 k/(i+1))\n            if j < k:\n                res[j] = item\n    return res","tests":[{"in":"reservoir_sample(list(range(10)), 3, 42)","out":"[4, 1, 9]"},{"in":"reservoir_sample(list(range(3)), 3, 42)","out":"[0, 1, 2]"},{"in":"reservoir_sample(list(range(5)), 5, 42)","out":"[0, 1, 2, 3, 4]"},{"in":"reservoir_sample([], 3, 42)","out":"[]"}],"edge":[{"in":"reservoir_sample(list(range(100)), 1, 42)","out":"[31]"}],"ex":"🎯 데이터 엔지니어링의 마법 같은 알고리즘입니다. 테라바이트 급의 로그 파일이 쏟아질 때, 파일 끝까지 읽기 전에 미리 몇 개인지도 모르면서 딱 1000개를 고르게 뽑아내고 싶을 때 메모리를 O(k) 만 쓰고 해냅니다.\n⚠️ 난수의 범위를 `random.randint(0, k)` 로 잘못 잡으면, 새로운 요소가 무조건 큰 확률로 기존 데이터를 밀어내어 최근 데이터 편향(Recency bias)이 극심해집니다. `0 ~ i` 로 잡아야 $N$ 번째 요소가 선택될 확률이 $\\frac{k}{N}$ 으로 딱 떨어지고, 수학적 귀납법에 의해 이전 요소가 살아남을 확률도 최종적으로 $\\frac{k}{N}$ 으로 균등해집니다.\n💡 이 알고리즘은 분산 시스템에서도 빛을 발합니다. 맵리듀스에서 여러 파티션별로 독립적인 저수지를 만들고 마지막에 이들을 다시 합치는 식으로 분산 병렬 샘플링이 가능합니다.\n🔧 실무 사례: 로그 모니터링 데몬이 에러 로그를 무한정 버퍼에 쌓지 못할 때, 메모리 10MB 크기의 저수지를 열어두면 과거부터 지금까지의 대표적인 에러 패턴을 균등하게 유지하며 개발자에게 보여줄 수 있습니다."}]}]}]);
